 23	/// Used to define a Sequence Paxos epoch
 24	#[derive(Clone, Copy, Eq, Debug, Default, PartialEq)]
 25	#[cfg_attr(feature = "serde", derive(Serialize, Deserialize))]
 26	pub struct Ballot {
 27	    /// The identifier for the configuration that the replica with this ballot is part of.
 28	    pub config_id: ConfigurationId,
 29	    /// Ballot number
 30	    pub n: u32,
 31	    /// Custom priority parameter
 32	    pub priority: u32,
 33	    /// The pid of the process
 34	    pub pid: NodeId,
 35	}
