 37	impl Ballot {
 38	    /// Creates a new Ballot
 39	    /// # Arguments
 40	    /// * `config_id` - The identifier for the configuration that the replica with this ballot is part of.
 41	    /// * `n` - Ballot number.
 42	    /// * `pid` -  Used as tiebreaker for total ordering of ballots.
 43	    pub fn with(config_id: ConfigurationId, n: u32, priority: u32, pid: NodeId) -> Ballot {
 44	        Ballot {
 45	            config_id,
 46	            n,
 47	            priority,
 48	            pid,
 49	        }
 50	    }
 51	}
