 65	const INITIAL_ROUND: u32 = 1;
 66	const RECOVERY_ROUND: u32 = 0;
 67	
 68	/// A Ballot Leader Election component. Used in conjunction with OmniPaxos to handle the election of a leader for a cluster of OmniPaxos servers,
 69	/// incoming messages and produces outgoing messages that the user has to fetch periodically and send using a network implementation.
 70	/// User also has to periodically fetch the decided entries that are guaranteed to be strongly consistent and linearizable, and therefore also safe to be used in the higher level application.
 71	pub(crate) struct BallotLeaderElection {
 72	    /// The identifier for the configuration that this instance is part of.
 73	    configuration_id: ConfigurationId,
 74	    /// Process identifier used to uniquely identify this instance.
 75	    pid: NodeId,
 76	    /// Vector that holds the pids of all the other servers.
 77	    peers: Vec<NodeId>,
 78	    /// The current round of the heartbeat cycle.
 79	    hb_round: u32,
 80	    /// The heartbeat replies this instance received during the current round.
 81	    heartbeat_replies: Vec<HeartbeatReply>,
 82	    /// Vector that holds all the received heartbeats from the previous heartbeat round, including the current node. Only used to display the connectivity of this node in the UI.
 83	    /// Represents nodes that are currently alive from the view of the current node.
 84	    prev_replies: Vec<HeartbeatReply>,
 85	    /// Holds the current ballot of this instance.
 86	    current_ballot: Ballot,
 87	    /// The current leader of this instance.
 88	    leader: Ballot,
 89	    /// A happy node either sees that it is, is connected to, or sees evidence of a potential leader
 90	    /// for the cluster. If a node is unhappy then it is seeking a new leader.
 91	    happy: bool,
 92	    /// The number of replicas inside the cluster whose heartbeats are needed to become and remain the leader.
 93	    quorum: Quorum,
 94	    /// Vector which holds all the outgoing messages of the BLE instance.
 95	    outgoing: Vec<BLEMessage>,
 96	    /// Logger used to output the status of the component.
 97	    #[cfg(feature = "logging")]
 98	    logger: Logger,
 99	}
100	
101	impl BallotLeaderElection {
102	    /// Construct a new BallotLeaderElection node
103	    pub(crate) fn with(config: BLEConfig, recovered_leader: Option<Ballot>) -> Self {
104	        let config_id = config.configuration_id;
105	        let pid = config.pid;
106	        let peers = config.peers;
107	        let num_nodes = &peers.len() + 1;
108	        let quorum = Quorum::with(config.flexible_quorum, num_nodes);
109	        let mut initial_ballot = Ballot::with(config_id, INITIAL_ROUND, config.priority, pid);
110	        let initial_leader = match recovered_leader {
111	            Some(b) if b != Ballot::default() => {
112	                // Prevents a recovered server from retaining BLE leadership with the same ballot.
113	                initial_ballot.n = RECOVERY_ROUND;
114	                b
115	            }
116	            _ => initial_ballot,
117	        };
118	        let mut ble = BallotLeaderElection {
119	            configuration_id: config_id,
120	            pid,
121	            peers,
122	            hb_round: 0,
123	            heartbeat_replies: Vec::with_capacity(num_nodes),
124	            prev_replies: Vec::with_capacity(num_nodes),
125	            current_ballot: initial_ballot,
126	            leader: initial_leader,
127	            happy: true,
128	            quorum,
129	            outgoing: Vec::with_capacity(config.buffer_size),
130	            #[cfg(feature = "logging")]
131	            logger: {
132	                if let Some(logger) = config.custom_logger {
133	                    logger
134	                } else {
135	                    let s = config
136	                        .logger_file_path
137	                        .unwrap_or_else(|| format!("logs/paxos_{}.log", pid));
138	                    create_logger(s.as_str())
139	                }
140	            },
141	        };
142	        #[cfg(feature = "logging")]
143	        {
144	            info!(
145	                ble.logger,
146	                "Ballot Leader Election component pid: {} created!", pid
147	            );
148	        }
149	        ble.new_hb_round();
150	        ble
151	    }
152	
153	    /// Update the custom priority used in the Ballot for this server. Note that changing the
154	    /// priority triggers a leader re-election.
155	    pub(crate) fn set_priority(&mut self, p: u32) {
156	        self.current_ballot.priority = p;
157	    }
158	
159	    /// Returns reference to outgoing messages
160	    pub(crate) fn outgoing_mut(&mut self) -> &mut Vec<BLEMessage> {
161	        &mut self.outgoing
162	    }
163	
164	    /// Handle an incoming message.
165	    /// # Arguments
166	    /// * `m` - the message to be handled.
167	    pub(crate) fn handle(&mut self, m: BLEMessage) {
168	        match m.msg {
169	            HeartbeatMsg::Request(req) => self.handle_request(m.from, req),
170	            HeartbeatMsg::Reply(rep) => self.handle_reply(rep),
171	        }
172	    }
173	
174	    /// Initiates a new heartbeat round.
175	    pub(crate) fn new_hb_round(&mut self) {
176	        self.prev_replies = std::mem::take(&mut self.heartbeat_replies);
177	        self.hb_round += 1;
178	        #[cfg(feature = "logging")]
179	        trace!(
180	            self.logger,
181	            "Initiate new heartbeat round: {}",
182	            self.hb_round
183	        );
184	        for peer in &self.peers {
185	            let hb_request = HeartbeatRequest {
186	                round: self.hb_round,
187	            };
188	            self.outgoing.push(BLEMessage {
189	                from: self.pid,
190	                to: *peer,
191	                msg: HeartbeatMsg::Request(hb_request),
192	            });
193	        }
194	    }
195	
196	    /// End of a heartbeat round. Returns current leader and election status.
197	    pub(crate) fn hb_timeout(
198	        &mut self,
199	        seq_paxos_state: &(Role, Phase),
200	        seq_paxos_promise: Ballot,
201	    ) -> Option<Ballot> {
202	        self.update_leader();
203	        self.update_happiness(seq_paxos_state);
204	        self.check_takeover();
205	        self.new_hb_round();
206	        if seq_paxos_promise > self.leader {
207	            // Sync leader with Paxos promise in case ballot didn't make it to BLE followers
208	            // or become_leader() was called.
209	            self.leader = seq_paxos_promise;
210	            if seq_paxos_promise.pid == self.pid {
211	                self.current_ballot = seq_paxos_promise;
212	            }
213	            self.happy = true;
214	        }
215	        if self.leader == self.current_ballot {
216	            Some(self.current_ballot)
217	        } else {
218	            None
219	        }
220	    }
221	
222	    fn update_leader(&mut self) {
223	        let max_reply_ballot = self.heartbeat_replies.iter().map(|r| r.ballot).max();
224	        if let Some(max) = max_reply_ballot {
225	            if max > self.leader {
226	                self.leader = max;
227	            }
228	        }
229	    }
230	
231	    fn update_happiness(&mut self, seq_paxos_state: &(Role, Phase)) {
232	        self.happy = if self.leader == self.current_ballot {
233	            let potential_followers = self
234	                .heartbeat_replies
235	                .iter()
236	                .filter(|hb_reply| hb_reply.leader <= self.current_ballot)
237	                .count();
238	            let can_form_quorum = match seq_paxos_state {
239	                (Role::Leader, Phase::Accept) => {
240	                    self.quorum.is_accept_quorum(potential_followers + 1)
241	                }
242	                _ => self.quorum.is_prepare_quorum(potential_followers + 1),
243	            };
244	            if can_form_quorum {
245	                true
246	            } else {
247	                let see_larger_happy_leader = self
248	                    .heartbeat_replies
249	                    .iter()
250	                    .any(|r| r.leader > self.current_ballot && r.happy);
251	                see_larger_happy_leader
252	            }
253	        } else {
254	            self.heartbeat_replies
255	                .iter()
256	                .any(|r| r.ballot == self.leader && r.happy)
257	        };
258	    }
259	
260	    fn check_takeover(&mut self) {
261	        if !self.happy {
262	            let all_neighbors_unhappy = self.heartbeat_replies.iter().all(|r| !r.happy);
263	            let im_quorum_connected = self
264	                .quorum
265	                .is_prepare_quorum(self.heartbeat_replies.len() + 1);
266	            if all_neighbors_unhappy && im_quorum_connected {
267	                // We increment past our leader instead of max of unhappy ballots because we
268	                // assume we have already checked leader for this round so they should be equal
269	                self.current_ballot.n = self.leader.n + 1;
270	                self.leader = self.current_ballot;
271	                self.happy = true;
272	            }
273	        }
274	    }
275	
276	    fn handle_request(&mut self, from: NodeId, req: HeartbeatRequest) {
277	        let hb_reply = HeartbeatReply {
278	            round: req.round,
279	            ballot: self.current_ballot,
280	            leader: self.leader,
281	            happy: self.happy,
282	        };
283	        self.outgoing.push(BLEMessage {
284	            from: self.pid,
285	            to: from,
286	            msg: HeartbeatMsg::Reply(hb_reply),
287	        });
288	    }
289	
290	    fn handle_reply(&mut self, rep: HeartbeatReply) {
291	        if rep.round == self.hb_round && rep.ballot.config_id == self.configuration_id {
292	            self.heartbeat_replies.push(rep);
293	        }
294	    }
295	
296	    pub(crate) fn get_current_ballot(&self) -> Ballot {
297	        self.current_ballot
298	    }
299	
300	    pub(crate) fn get_ballots(&self) -> Vec<HeartbeatReply> {
301	        self.prev_replies.clone()
302	    }
303	}
