305	/// Configuration for `BallotLeaderElection`.
306	/// # Fields
307	/// * `configuration_id`: The identifier for the configuration that this node is part of.
308	/// * `pid`: The unique identifier of this node. Must not be 0.
309	/// * `peers`: The peers of this node i.e. the `pid`s of the other servers in the configuration.
310	/// * `priority`: Set custom priority for this node to be elected as the leader.
311	/// * `flexible_quorum` : Defines read and write quorum sizes. Can be used for different latency vs fault tolerance tradeoffs.
312	/// * `buffer_size`: The buffer size for outgoing messages.
313	/// * `logger_file_path`: The path where the default logger logs events.
314	#[derive(Clone, Debug)]
315	pub(crate) struct BLEConfig {
316	    configuration_id: ConfigurationId,
317	    pid: NodeId,
318	    peers: Vec<NodeId>,
319	    priority: u32,
320	    flexible_quorum: Option<FlexibleQuorum>,
321	    buffer_size: usize,
322	    #[cfg(feature = "logging")]
323	    logger_file_path: Option<String>,
324	    #[cfg(feature = "logging")]
325	    custom_logger: Option<Logger>,
326	}
327	
328	impl From<OmniPaxosConfig> for BLEConfig {
329	    fn from(config: OmniPaxosConfig) -> Self {
330	        let pid = config.server_config.pid;
331	        let peers = config
332	            .cluster_config
333	            .nodes
334	            .into_iter()
335	            .filter(|x| *x != pid)
336	            .collect();
337	
338	        Self {
339	            configuration_id: config.cluster_config.configuration_id,
340	            pid,
341	            peers,
342	            priority: config.server_config.leader_priority,
343	            flexible_quorum: config.cluster_config.flexible_quorum,
344	            buffer_size: BLE_BUFFER_SIZE,
345	            #[cfg(feature = "logging")]
346	            logger_file_path: config.server_config.logger_file_path,
347	            #[cfg(feature = "logging")]
348	            custom_logger: config.server_config.custom_logger,
349	        }
350	    }
351	}

