 22	/// a Sequence Paxos replica. Maintains local state of the replicated log, handles incoming messages and produces outgoing messages that the user has to fetch periodically and send using a network implementation.
 23	/// User also has to periodically fetch the decided entries that are guaranteed to be strongly consistent and linearizable, and therefore also safe to be used in the higher level application.
 24	/// If snapshots are not desired to be used, use `()` for the type parameter `S`.
 25	pub(crate) struct SequencePaxos<T, B>
 26	where
 27	    T: Entry,
 28	    B: Storage<T>,
 29	{
 30	    pub(crate) internal_storage: InternalStorage<B, T>,
 31	    pid: NodeId,
 32	    peers: Vec<NodeId>, // excluding self pid
 33	    state: (Role, Phase),
 34	    buffered_proposals: Vec<T>,
 35	    buffered_stopsign: Option<StopSign>,
 36	    outgoing: Vec<Message<T>>,
 37	    leader_state: LeaderState<T>,
 38	    latest_accepted_meta: Option<(Ballot, usize)>,
 39	    // Keeps track of sequence of accepts from leader where AcceptSync = 1
 40	    current_seq_num: SequenceNumber,
 41	    cached_promise_message: Option<Promise<T>>,
 42	    #[cfg(feature = "logging")]
