 51	    /*** User functions ***/
 52	    /// Creates a Sequence Paxos replica.
 53	    pub(crate) fn with(config: SequencePaxosConfig, storage: B) -> Self {
 54	        let pid = config.pid;
 55	        let peers = config.peers;
 56	        let num_nodes = &peers.len() + 1;
 57	        let quorum = Quorum::with(config.flexible_quorum, num_nodes);
 58	        let max_peer_pid = peers.iter().max().unwrap();
 59	        let max_pid = *std::cmp::max(max_peer_pid, &pid) as usize;
 60	        let mut outgoing = Vec::with_capacity(config.buffer_size);
