 63	            .expect("storage error while trying to read promise")
 64	        {
 65	            // if we recover a promise from storage then we must do failure recovery
 66	            Some(b) => {
 67	                let state = (Role::Follower, Phase::Recover);
 68	                for peer_pid in &peers {
 69	                    let prepreq = PrepareReq { n: b };
 70	                    outgoing.push(Message::SequencePaxos(PaxosMessage {
 71	                        from: pid,
 72	                        to: *peer_pid,
 73	                        msg: PaxosMsg::PrepareReq(prepreq),
 74	                    }));
 75	                }
 76	                (state, b)
 77	            }
 78	            None => ((Role::Follower, Phase::None), Ballot::default()),
 79	        };
 80	        let internal_storage_config = InternalStorageConfig {
 81	            batch_size: config.batch_size,
 82	        };
 83	        let mut paxos = SequencePaxos {
 84	            internal_storage: InternalStorage::with(
 85	                storage,
 86	                internal_storage_config,
 87	                #[cfg(feature = "unicache")]
 88	                pid,
 89	            ),
 90	            pid,
 91	            peers,
 92	            state,
 93	            buffered_proposals: vec![],
 94	            buffered_stopsign: None,
 95	            outgoing,
 96	            leader_state: LeaderState::<T>::with(leader, max_pid, quorum),
 97	            latest_accepted_meta: None,
 98	            current_seq_num: SequenceNumber::default(),
 99	            cached_promise_message: None,
100	            #[cfg(feature = "logging")]
101	            logger: {
102	                if let Some(logger) = config.custom_logger {
103	                    logger
104	                } else {
105	                    let s = config
106	                        .logger_file_path
107	                        .unwrap_or_else(|| format!("logs/paxos_{}.log", pid));
108	                    create_logger(s.as_str())
109	                }
110	            },
111	        };
112	        paxos
113	            .internal_storage
114	            .set_promise(leader)
115	            .expect(WRITE_ERROR_MSG);
116	        #[cfg(feature = "logging")]
117	        {
118	            info!(paxos.logger, "Paxos component pid: {} created!", pid);
119	            if let Quorum::Flexible(flex_quorum) = quorum {
120	                if flex_quorum.read_quorum_size > num_nodes - flex_quorum.write_quorum_size + 1 {
121	                    warn!(
122	                        paxos.logger,
123	                        "Unnecessary overlaps in read and write quorums. Read and Write quorums only need to be overlapping by one node i.e., read_quorum_size + write_quorum_size = num_nodes + 1");
124	                }
125	            }
126	        }
127	        paxos
128	    }
