138	    /// Initiates the trim process.
139	    /// # Arguments
140	    /// * `trim_idx` - Deletes all entries up to [`trim_idx`], if the [`trim_idx`] is `None` then the minimum index accepted by **ALL** servers will be used as the [`trim_idx`].
141	    pub(crate) fn trim(&mut self, trim_idx: Option<usize>) -> Result<(), CompactionErr> {
142	        match self.state {
143	            (Role::Leader, _) => {
144	                let min_all_accepted_idx = self.leader_state.get_min_all_accepted_idx();
145	                let trimmed_idx = match trim_idx {
146	                    Some(idx) if idx <= *min_all_accepted_idx => idx,
147	                    None => {
148	                        #[cfg(feature = "logging")]
149	                        trace!(
150	                            self.logger,
151	                            "No trim index provided, using min_las_idx: {:?}",
152	                            min_all_accepted_idx
153	                        );
154	                        *min_all_accepted_idx
155	                    }
156	                    _ => {
157	                        return Err(CompactionErr::NotAllDecided(*min_all_accepted_idx));
158	                    }
159	                };
160	                let result = self.internal_storage.try_trim(trimmed_idx);
161	                if result.is_ok() {
162	                    for pid in &self.peers {
163	                        let msg = PaxosMsg::Compaction(Compaction::Trim(trimmed_idx));
164	                        self.outgoing.push(Message::SequencePaxos(PaxosMessage {
165	                            from: self.pid,
166	                            to: *pid,
167	                            msg,
168	                        }));
169	                    }
170	                }
171	                result.map_err(|e| {
172	                    *e.downcast()
173	                        .expect("storage error while trying to trim log")
174	                })
175	            }
176	            _ => Err(CompactionErr::NotCurrentLeader(self.get_current_leader())),
177	        }
178	    }
179	
180	    /// Trim the log and create a snapshot. ** Note: only up to the `decided_idx` can be snapshotted **
181	    /// # Arguments
182	    /// `idx` - Snapshots all entries with index < [`idx`], if the [`idx`] is None then the decided index will be used.
183	    /// `local_only` - If `true`, only this server snapshots the log. If `false` all servers performs the snapshot.
184	    pub(crate) fn snapshot(
185	        &mut self,
186	        idx: Option<usize>,
187	        local_only: bool,
188	    ) -> Result<(), CompactionErr> {
189	        let result = self.internal_storage.try_snapshot(idx);
190	        if !local_only && result.is_ok() {
191	            // since it is decided, it is ok even for a follower to send this
192	            for pid in &self.peers {
193	                let msg = PaxosMsg::Compaction(Compaction::Snapshot(idx));
194	                self.outgoing.push(Message::SequencePaxos(PaxosMessage {
195	                    from: self.pid,
196	                    to: *pid,
197	                    msg,
198	                }));
199	            }
200	        }
201	        result.map_err(|e| {
202	            *e.downcast()
203	                .expect("storage error while trying to snapshot log")
204	        })
205	    }
