217	    fn handle_compaction(&mut self, c: Compaction) {
218	        // try trimming and snapshotting forwarded compaction. Errors are ignored as that the data will still be kept.
219	        match c {
220	            Compaction::Trim(idx) => {
221	                let _ = self.internal_storage.try_trim(idx);
222	            }
223	            Compaction::Snapshot(idx) => {
224	                let _ = self.snapshot(idx, true);
225	            }
226	        }
227	    }
