229	    /// Detects if a Prepare, Promise, AcceptStopSign, Decide of a Stopsign, or PrepareReq message
230	    /// has been sent but not been received. If so resends them. Note: We can't detect if a
231	    /// StopSign's Decide message has been received so we always resend to be safe.
232	    pub(crate) fn resend_message_timeout(&mut self) {
233	        match self.state.0 {
234	            Role::Leader => self.resend_messages_leader(),
235	            Role::Follower => self.resend_messages_follower(),
236	        }
237	    }
