239	    /// Flushes any batched log entries and sends their corresponding Accept or Accepted messages.
240	    pub(crate) fn flush_batch_timeout(&mut self) {
241	        match self.state {
242	            (Role::Leader, Phase::Accept) => self.flush_batch_leader(),
243	            (Role::Follower, Phase::Accept) => self.flush_batch_follower(),
244	            _ => (),
245	        }
246	    }
