248	    /// Moves the outgoing messages from this replica into the buffer. The messages should then be sent via the network implementation.
249	    /// If `buffer` is empty, it gets swapped with the internal message buffer. Otherwise, messages are appended to the buffer. This prevents messages from getting discarded.
250	    /// the buffer.
251	    pub(crate) fn take_outgoing_msgs(&mut self, buffer: &mut Vec<Message<T>>) {
252	        if buffer.is_empty() {
253	            std::mem::swap(buffer, &mut self.outgoing);
254	        } else {
255	            // User has unsent messages in their buffer, must extend their buffer.
256	            buffer.append(&mut self.outgoing);
257	        }
258	        self.leader_state.reset_latest_accept_meta();
259	        self.latest_accepted_meta = None;
260	    }
