262	    /// Handle an incoming message.
263	    pub(crate) fn handle(&mut self, m: PaxosMessage<T>) {
264	        match m.msg {
265	            PaxosMsg::PrepareReq(prepreq) => self.handle_preparereq(prepreq, m.from),
266	            PaxosMsg::Prepare(prep) => self.handle_prepare(prep, m.from),
267	            PaxosMsg::Promise(prom) => match &self.state {
268	                (Role::Leader, Phase::Prepare) => self.handle_promise_prepare(prom, m.from),
269	                (Role::Leader, Phase::Accept) => self.handle_promise_accept(prom, m.from),
270	                _ => {}
271	            },
272	            PaxosMsg::AcceptSync(acc_sync) => self.handle_acceptsync(acc_sync, m.from),
273	            PaxosMsg::AcceptDecide(acc) => self.handle_acceptdecide(acc),
274	            PaxosMsg::NotAccepted(not_acc) => self.handle_notaccepted(not_acc, m.from),
275	            PaxosMsg::Accepted(accepted) => self.handle_accepted(accepted, m.from),
276	            PaxosMsg::Decide(d) => self.handle_decide(d),
277	            PaxosMsg::ProposalForward(proposals) => self.handle_forwarded_proposal(proposals),
278	            PaxosMsg::Compaction(c) => self.handle_compaction(c),
279	            PaxosMsg::AcceptStopSign(acc_ss) => self.handle_accept_stopsign(acc_ss),
280	            PaxosMsg::ForwardStopSign(f_ss) => self.handle_forwarded_stopsign(f_ss),
281	        }
282	    }
