297	    /// Append an entry to the replicated log.
298	    pub(crate) fn append(&mut self, entry: T) -> Result<(), ProposeErr<T>> {
299	        if self.accepted_reconfiguration() {
300	            Err(ProposeErr::PendingReconfigEntry(entry))
301	        } else {
302	            self.propose_entry(entry);
303	            Ok(())
304	        }
