307	    /// Propose a reconfiguration. Returns an error if already stopped or `new_config` is invalid.
308	    /// `new_config` defines the cluster-wide configuration settings for the next cluster.
309	    /// `metadata` is optional data to commit alongside the reconfiguration.
310	    pub(crate) fn reconfigure(
311	        &mut self,
312	        new_config: ClusterConfig,
313	        metadata: Option<Vec<u8>>,
314	    ) -> Result<(), ProposeErr<T>> {
315	        if self.accepted_reconfiguration() {
316	            return Err(ProposeErr::PendingReconfigConfig(new_config, metadata));
317	        }
318	        #[cfg(feature = "logging")]
319	        info!(
320	            self.logger,
321	            "Accepting reconfiguration {:?}", new_config.nodes
322	        );
323	        let ss = StopSign::with(new_config, metadata);
324	        match self.state {
325	            (Role::Leader, Phase::Prepare) => self.buffered_stopsign = Some(ss),
326	            (Role::Leader, Phase::Accept) => self.accept_stopsign_leader(ss),
327	            _ => self.forward_stopsign(ss),
328	        }
329	        Ok(())
330	    }
