341	    /// Handles re-establishing a connection to a previously disconnected peer.
342	    /// This should only be called if the underlying network implementation indicates that a connection has been re-established.
343	    pub(crate) fn reconnected(&mut self, pid: NodeId) {
344	        if pid == self.pid {
345	            return;
346	        } else if pid == self.get_current_leader() {
347	            self.state = (Role::Follower, Phase::Recover);
348	        }
349	        let prepreq = PrepareReq {
350	            n: self.get_promise(),
351	        };
352	        self.outgoing.push(Message::SequencePaxos(PaxosMessage {
353	            from: self.pid,
354	            to: pid,
355	            msg: PaxosMsg::PrepareReq(prepreq),
356	        }));
357	    }
