359	    fn propose_entry(&mut self, entry: T) {
360	        match self.state {
361	            (Role::Leader, Phase::Prepare) => self.buffered_proposals.push(entry),
362	            (Role::Leader, Phase::Accept) => self.accept_entry_leader(entry),
363	            _ => self.forward_proposals(vec![entry]),
364	        }
365	    }
