371	    pub(crate) fn forward_proposals(&mut self, mut entries: Vec<T>) {
372	        let leader = self.get_current_leader();
373	        if leader > 0 && self.pid != leader {
374	            let pf = PaxosMsg::ProposalForward(entries);
375	            let msg = Message::SequencePaxos(PaxosMessage {
376	                from: self.pid,
377	                to: leader,
378	                msg: pf,
379	            });
380	            self.outgoing.push(msg);
381	        } else {
382	            self.buffered_proposals.append(&mut entries);
383	        }
384	    }
385	
386	    pub(crate) fn forward_stopsign(&mut self, ss: StopSign) {
387	        let leader = self.get_current_leader();
388	        if leader > 0 && self.pid != leader {
389	            #[cfg(feature = "logging")]
390	            trace!(self.logger, "Forwarding StopSign to Leader {:?}", leader);
391	            let fs = PaxosMsg::ForwardStopSign(ss);
392	            let msg = Message::SequencePaxos(PaxosMessage {
393	                from: self.pid,
394	                to: leader,
395	                msg: fs,
396	            });
397	            self.outgoing.push(msg);
398	        } else if self.buffered_stopsign.as_mut().is_none() {
399	            self.buffered_stopsign = Some(ss);
400	        }
401	    }
402	    /// Returns `LogSync`, a struct to help other servers synchronize their log to correspond to the
403	    /// current state of our own log. The `common_prefix_idx` marks where in the log the other server
404	    /// needs to be sync from.
405	    fn create_log_sync(
406	        &self,
407	        common_prefix_idx: usize,
408	        other_logs_decided_idx: usize,
409	    ) -> LogSync<T> {
410	        let decided_idx = self.internal_storage.get_decided_idx();
411	        let (decided_snapshot, suffix, sync_idx) =
412	            if T::Snapshot::use_snapshots() && decided_idx > common_prefix_idx {
413	                // Note: We snapshot from the other log's decided index and not the common prefix because
414	                // snapshots currently only work on decided entries.
415	                let (delta_snapshot, compacted_idx) = self
416	                    .internal_storage
417	                    .create_diff_snapshot(other_logs_decided_idx)
418	                    .expect(READ_ERROR_MSG);
419	                let suffix = self
420	                    .internal_storage
421	                    .get_suffix(decided_idx)
422	                    .expect(READ_ERROR_MSG);
423	                (delta_snapshot, suffix, compacted_idx)
424	            } else {
425	                let suffix = self
426	                    .internal_storage
427	                    .get_suffix(common_prefix_idx)
428	                    .expect(READ_ERROR_MSG);
429	                (None, suffix, common_prefix_idx)
430	            };
431	        LogSync {
432	            decided_snapshot,
433	            suffix,
434	            sync_idx,
435	            stopsign: self.internal_storage.get_stopsign(),
436	        }
437	    }
438	}
