454	/// Configuration for `SequencePaxos`.
455	/// # Fields
456	/// * `pid`: The unique identifier of this node. Must not be 0.
457	/// * `peers`: The peers of this node i.e. the `pid`s of the other servers in the configuration.
458	/// * `flexible_quorum` : Defines read and write quorum sizes. Can be used for different latency vs fault tolerance tradeoffs.
459	/// * `buffer_size`: The buffer size for outgoing messages.
460	/// * `batch_size`: The size of the buffer for log batching. The default is 1, which means no batching.
461	/// * `logger_file_path`: The path where the default logger logs events.
462	#[derive(Clone, Debug)]
463	pub(crate) struct SequencePaxosConfig {
464	    pid: NodeId,
