 13	{
 14	    /// Handle a new leader. Should be called when the leader election has elected a new leader with the ballot `n`
 15	    /*** Leader ***/
 16	    pub(crate) fn handle_leader(&mut self, n: Ballot) {
 17	        if n <= self.leader_state.n_leader || n <= self.internal_storage.get_promise() {
 18	            return;
 19	        }
 20	        #[cfg(feature = "logging")]
 21	        debug!(self.logger, "Newly elected leader: {:?}", n);
 22	        if self.pid == n.pid {
 23	            self.leader_state =
 24	                LeaderState::with(n, self.leader_state.max_pid, self.leader_state.quorum);
 25	            // Flush any pending writes
 26	            // Don't have to handle flushed entries here because we will sync with followers
 27	            let _ = self.internal_storage.flush_batch().expect(WRITE_ERROR_MSG);
 28	            self.internal_storage.set_promise(n).expect(WRITE_ERROR_MSG);
 29	            /* insert my promise */
 30	            let na = self.internal_storage.get_accepted_round();
 31	            let decided_idx = self.get_decided_idx();
 32	            let accepted_idx = self.internal_storage.get_accepted_idx();
 33	            let my_promise = Promise {
 34	                n,
 35	                n_accepted: na,
 36	                decided_idx,
 37	                accepted_idx,
 38	                log_sync: None,
 39	            };
 40	            self.leader_state.set_promise(my_promise, self.pid, true);
 41	            /* initialise longest chosen sequence and update state */
 42	            self.state = (Role::Leader, Phase::Prepare);
 43	            let prep = Prepare {
 44	                n,
 45	                decided_idx,
 46	                n_accepted: na,
 47	                accepted_idx,
 48	            };
 49	            /* send prepare */
 50	            for pid in &self.peers {
 51	                self.outgoing.push(Message::SequencePaxos(PaxosMessage {
 52	                    from: self.pid,
 53	                    to: *pid,
 54	                    msg: PaxosMsg::Prepare(prep),
 55	                }));
 56	            }
 57	        } else {
 58	            self.become_follower();
 59	        }
 60	    }
