 66	    pub(crate) fn handle_preparereq(&mut self, prepreq: PrepareReq, from: NodeId) {
 67	        #[cfg(feature = "logging")]
 68	        debug!(self.logger, "Incoming message PrepareReq from {}", from);
 69	        if self.state.0 == Role::Leader && prepreq.n <= self.leader_state.n_leader {
 70	            self.leader_state.reset_promise(from);
 71	            self.leader_state.set_latest_accept_meta(from, None);
 72	            self.send_prepare(from);
 73	        }
 74	    }
