 78	            match self.state {
 79	                (Role::Leader, Phase::Prepare) => self.buffered_proposals.append(&mut entries),
 80	                (Role::Leader, Phase::Accept) => self.accept_entries_leader(entries),
 81	                _ => self.forward_proposals(entries),
 82	            }
 83	        }
 84	    }
