 91	            (Role::Leader, Phase::Prepare) => self.buffered_stopsign = Some(ss),
 92	            (Role::Leader, Phase::Accept) => self.accept_stopsign_leader(ss),
 93	            _ => self.forward_stopsign(ss),
 94	        }
 95	    }
