100	            decided_idx: self.internal_storage.get_decided_idx(),
101	            n_accepted: self.internal_storage.get_accepted_round(),
102	            accepted_idx: self.internal_storage.get_accepted_idx(),
103	        };
104	        self.outgoing.push(Message::SequencePaxos(PaxosMessage {
105	            from: self.pid,
106	            to,
107	            msg: PaxosMsg::Prepare(prep),
108	        }));
109	    }
