135	    pub(crate) fn accept_stopsign_leader(&mut self, ss: StopSign) {
136	        let accepted_metadata = self
137	            .internal_storage
138	            .append_stopsign(ss.clone())
139	            .expect(WRITE_ERROR_MSG);
140	        if let Some(metadata) = accepted_metadata {
141	            self.send_acceptdecide(metadata);
142	        }
143	        let accepted_idx = self.internal_storage.get_accepted_idx();
144	        self.leader_state.set_accepted_idx(self.pid, accepted_idx);
145	        for pid in self.leader_state.get_promised_followers() {
146	            self.send_accept_stopsign(pid, ss.clone(), false);
147	        }
148	    }
149	
150	    fn send_accsync(&mut self, to: NodeId) {
151	        let current_n = self.leader_state.n_leader;
152	        let PromiseMetaData {
153	            n_accepted: prev_round_max_promise_n,
154	            accepted_idx: prev_round_max_accepted_idx,
155	            ..
156	        } = &self.leader_state.get_max_promise_meta();
157	        let PromiseMetaData {
158	            n_accepted: followers_promise_n,
159	            accepted_idx: followers_accepted_idx,
160	            pid,
161	            ..
162	        } = self.leader_state.get_promise_meta(to);
163	        let followers_decided_idx = self
164	            .leader_state
165	            .get_decided_idx(*pid)
166	            .expect("Received PromiseMetaData but not found in ld");
167	        // Follower can have valid accepted entries depending on which leader they were previously following
168	        let followers_valid_entries_idx = if *followers_promise_n == current_n {
169	            *followers_accepted_idx
170	        } else if *followers_promise_n == *prev_round_max_promise_n {
171	            *prev_round_max_accepted_idx.min(followers_accepted_idx)
172	        } else {
173	            followers_decided_idx
174	        };
175	        let log_sync = self.create_log_sync(followers_valid_entries_idx, followers_decided_idx);
176	        self.leader_state.increment_seq_num_session(to);
177	        let acc_sync = AcceptSync {
178	            n: current_n,
179	            seq_num: self.leader_state.next_seq_num(to),
180	            decided_idx: self.get_decided_idx(),
181	            log_sync,
182	            #[cfg(feature = "unicache")]
183	            unicache: self.internal_storage.get_unicache(),
184	        };
185	        let msg = Message::SequencePaxos(PaxosMessage {
186	            from: self.pid,
187	            to,
188	            msg: PaxosMsg::AcceptSync(acc_sync),
189	        });
190	        self.outgoing.push(msg);
191	    }
192	
193	    fn send_acceptdecide(&mut self, accepted: AcceptedMetaData<T>) {
194	        let decided_idx = self.internal_storage.get_decided_idx();
195	        for pid in self.leader_state.get_promised_followers() {
196	            let latest_accdec = self.get_latest_accdec_message(pid);
197	            match latest_accdec {
198	                // Modify existing AcceptDecide message to follower
199	                Some(accdec) => {
200	                    accdec.entries.extend(accepted.entries.iter().cloned());
201	                    accdec.decided_idx = decided_idx;
202	                }
203	                // Add new AcceptDecide message to follower
204	                None => {
205	                    self.leader_state
206	                        .set_latest_accept_meta(pid, Some(self.outgoing.len()));
207	                    let acc = AcceptDecide {
208	                        n: self.leader_state.n_leader,
209	                        seq_num: self.leader_state.next_seq_num(pid),
210	                        decided_idx,
211	                        entries: accepted.entries.clone(),
212	                    };
213	                    self.outgoing.push(Message::SequencePaxos(PaxosMessage {
214	                        from: self.pid,
215	                        to: pid,
216	                        msg: PaxosMsg::AcceptDecide(acc),
217	                    }));
218	                }
219	            }
220	        }
221	    }
222	
223	    fn send_accept_stopsign(&mut self, to: NodeId, ss: StopSign, resend: bool) {
224	        let seq_num = match resend {
225	            true => self.leader_state.get_seq_num(to),
226	            false => self.leader_state.next_seq_num(to),
227	        };
228	        let acc_ss = PaxosMsg::AcceptStopSign(AcceptStopSign {
229	            seq_num,
230	            n: self.leader_state.n_leader,
231	            ss,
232	        });
233	        self.outgoing.push(Message::SequencePaxos(PaxosMessage {
234	            from: self.pid,
235	            to,
236	            msg: acc_ss,
237	        }));
238	    }
239	
240	    pub(crate) fn send_decide(&mut self, to: NodeId, decided_idx: usize, resend: bool) {
241	        let seq_num = match resend {
242	            true => self.leader_state.get_seq_num(to),
243	            false => self.leader_state.next_seq_num(to),
244	        };
245	        let d = Decide {
246	            n: self.leader_state.n_leader,
247	            seq_num,
248	            decided_idx,
249	        };
250	        self.outgoing.push(Message::SequencePaxos(PaxosMessage {
251	            from: self.pid,
252	            to,
253	            msg: PaxosMsg::Decide(d),
254	        }));
255	    }
256	
257	    fn handle_majority_promises(&mut self) {
258	        let max_promise_sync = self.leader_state.take_max_promise_sync();
259	        let decided_idx = self.leader_state.get_max_decided_idx();
260	        let mut new_accepted_idx = self
261	            .internal_storage
262	            .sync_log(self.leader_state.n_leader, decided_idx, max_promise_sync)
263	            .expect(WRITE_ERROR_MSG);
264	        if !self.accepted_reconfiguration() {
265	            if !self.buffered_proposals.is_empty() {
266	                let entries = std::mem::take(&mut self.buffered_proposals);
267	                new_accepted_idx = self
268	                    .internal_storage
269	                    .append_entries_without_batching(entries)
270	                    .expect(WRITE_ERROR_MSG);
271	            }
272	            if let Some(ss) = self.buffered_stopsign.take() {
273	                self.internal_storage
274	                    .append_stopsign(ss)
275	                    .expect(WRITE_ERROR_MSG);
276	                new_accepted_idx = self.internal_storage.get_accepted_idx();
277	            }
278	        }
279	        self.state = (Role::Leader, Phase::Accept);
280	        self.leader_state
281	            .set_accepted_idx(self.pid, new_accepted_idx);
282	        for pid in self.leader_state.get_promised_followers() {
283	            self.send_accsync(pid);
284	        }
285	    }
286	
287	    pub(crate) fn handle_promise_prepare(&mut self, prom: Promise<T>, from: NodeId) {
288	        #[cfg(feature = "logging")]
289	        debug!(
290	            self.logger,
291	            "Handling promise from {} in Prepare phase", from
292	        );
293	        if prom.n == self.leader_state.n_leader {
294	            let received_majority = self.leader_state.set_promise(prom, from, true);
295	            if received_majority {
296	                self.handle_majority_promises();
297	            }
298	        }
299	    }
300	
301	    pub(crate) fn handle_promise_accept(&mut self, prom: Promise<T>, from: NodeId) {
302	        #[cfg(feature = "logging")]
303	        {
304	            let (r, p) = &self.state;
305	            debug!(
306	                self.logger,
307	                "Self role {:?}, phase {:?}. Incoming message Promise Accept from {}", r, p, from
308	            );
309	        }
310	        if prom.n == self.leader_state.n_leader {
311	            self.leader_state.set_promise(prom, from, false);
312	            self.send_accsync(from);
313	        }
314	    }
315	
316	    pub(crate) fn handle_accepted(&mut self, accepted: Accepted, from: NodeId) {
317	        #[cfg(feature = "logging")]
318	        trace!(
319	            self.logger,
320	            "Got Accepted from {}, idx: {}, chosen_idx: {}, accepted: {:?}",
321	            from,
322	            accepted.accepted_idx,
323	            self.internal_storage.get_decided_idx(),
324	            self.leader_state.accepted_indexes
325	        );
326	        if accepted.n == self.leader_state.n_leader && self.state == (Role::Leader, Phase::Accept) {
327	            self.leader_state
328	                .set_accepted_idx(from, accepted.accepted_idx);
329	            if accepted.accepted_idx > self.internal_storage.get_decided_idx()
330	                && self.leader_state.is_chosen(accepted.accepted_idx)
331	            {
332	                let decided_idx = accepted.accepted_idx;
333	                self.internal_storage
334	                    .set_decided_idx(decided_idx)
335	                    .expect(WRITE_ERROR_MSG);
336	                for pid in self.leader_state.get_promised_followers() {
337	                    let latest_accdec = self.get_latest_accdec_message(pid);
338	                    match latest_accdec {
339	                        Some(accdec) => accdec.decided_idx = decided_idx,
340	                        None => self.send_decide(pid, decided_idx, false),
341	                    }
342	                }
343	            }
344	        }
345	    }
346	
347	    fn get_latest_accdec_message(&mut self, to: NodeId) -> Option<&mut AcceptDecide<T>> {
348	        if let Some((bal, outgoing_idx)) = self.leader_state.get_latest_accept_meta(to) {
349	            if bal == self.leader_state.n_leader {
350	                if let Message::SequencePaxos(PaxosMessage {
351	                    msg: PaxosMsg::AcceptDecide(accdec),
352	                    ..
353	                }) = self.outgoing.get_mut(outgoing_idx).unwrap()
354	                {
355	                    return Some(accdec);
356	                } else {
357	                    #[cfg(feature = "logging")]
358	                    debug!(self.logger, "Cached idx is not an AcceptedDecide!");
359	                }
360	            }
361	        }
362	        None
363	    }
364	
365	    pub(crate) fn handle_notaccepted(&mut self, not_acc: NotAccepted, from: NodeId) {
366	        if self.state.0 == Role::Leader && self.leader_state.n_leader < not_acc.n {
367	            self.leader_state.lost_promise(from);
368	        }
369	    }
370	
371	    pub(crate) fn resend_messages_leader(&mut self) {
372	        match self.state.1 {
373	            Phase::Prepare => {
374	                // Resend Prepare
375	                let preparable_peers = self.leader_state.get_preparable_peers(&self.peers);
376	                for peer in preparable_peers {
377	                    self.send_prepare(peer);
378	                }
379	            }
380	            Phase::Accept => {
381	                // Resend AcceptStopSign or StopSign's decide
382	                if let Some(ss) = self.internal_storage.get_stopsign() {
383	                    let decided_idx = self.internal_storage.get_decided_idx();
384	                    for follower in self.leader_state.get_promised_followers() {
385	                        if self.internal_storage.stopsign_is_decided() {
386	                            self.send_decide(follower, decided_idx, true);
387	                        } else if self.leader_state.get_accepted_idx(follower)
388	                            != self.internal_storage.get_accepted_idx()
389	                        {
390	                            self.send_accept_stopsign(follower, ss.clone(), true);
391	                        }
392	                    }
393	                }
394	                // Resend Prepare
395	                let preparable_peers = self.leader_state.get_preparable_peers(&self.peers);
396	                for peer in preparable_peers {
397	                    self.send_prepare(peer);
398	                }
399	            }
400	            Phase::Recover => (),
401	            Phase::None => (),
402	        }
403	    }
404	
405	    pub(crate) fn flush_batch_leader(&mut self) {
406	        let accepted_metadata = self
407	            .internal_storage
408	            .flush_batch_and_get_entries()
409	            .expect(WRITE_ERROR_MSG);
410	        if let Some(metadata) = accepted_metadata {
411	            self.leader_state
412	                .set_accepted_idx(self.pid, metadata.accepted_idx);
413	            self.send_acceptdecide(metadata);
414	        }
415	    }
416	}

