  7	impl<T, B> SequencePaxos<T, B>
  8	where
  9	    T: Entry,
 10	    B: Storage<T>,
 11	{
 12	    /*** Follower ***/
 13	    pub(crate) fn handle_prepare(&mut self, prep: Prepare, from: NodeId) {
 14	        let old_promise = self.internal_storage.get_promise();
 15	        if old_promise < prep.n || (old_promise == prep.n && self.state.1 == Phase::Recover) {
 16	            // Flush any pending writes
 17	            // Don't have to handle flushed entries here because we will sync with followers
 18	            let _ = self.internal_storage.flush_batch().expect(WRITE_ERROR_MSG);
 19	            self.internal_storage
 20	                .set_promise(prep.n)
 21	                .expect(WRITE_ERROR_MSG);
 22	            self.state = (Role::Follower, Phase::Prepare);
 23	            self.current_seq_num = SequenceNumber::default();
 24	            let na = self.internal_storage.get_accepted_round();
 25	            let accepted_idx = self.internal_storage.get_accepted_idx();
 26	            let log_sync = if na > prep.n_accepted {
 27	                // I'm more up to date: send leader what he is missing after his decided index.
 28	                Some(self.create_log_sync(prep.decided_idx, prep.decided_idx))
 29	            } else if na == prep.n_accepted && accepted_idx > prep.accepted_idx {
 30	                // I'm more up to date and in same round: send leader what he is missing after his
 31	                // accepted index.
 32	                Some(self.create_log_sync(prep.accepted_idx, prep.decided_idx))
 33	            } else {
 34	                // I'm equally or less up to date
 35	                None
 36	            };
 37	            let promise = Promise {
 38	                n: prep.n,
 39	                n_accepted: na,
 40	                decided_idx: self.internal_storage.get_decided_idx(),
 41	                accepted_idx,
 42	                log_sync,
 43	            };
 44	            self.cached_promise_message = Some(promise.clone());
 45	            self.outgoing.push(Message::SequencePaxos(PaxosMessage {
 46	                from: self.pid,
 47	                to: from,
 48	                msg: PaxosMsg::Promise(promise),
 49	            }));
 50	        }
 51	    }
 52	
 53	    pub(crate) fn handle_acceptsync(&mut self, accsync: AcceptSync<T>, from: NodeId) {
 54	        if self.check_valid_ballot(accsync.n) && self.state == (Role::Follower, Phase::Prepare) {
 55	            self.cached_promise_message = None;
 56	            let new_accepted_idx = self
 57	                .internal_storage
 58	                .sync_log(accsync.n, accsync.decided_idx, Some(accsync.log_sync))
 59	                .expect(WRITE_ERROR_MSG);
 60	            if self.internal_storage.get_stopsign().is_none() {
 61	                self.forward_buffered_proposals();
 62	            }
 63	            let accepted = Accepted {
 64	                n: accsync.n,
 65	                accepted_idx: new_accepted_idx,
 66	            };
 67	            self.state = (Role::Follower, Phase::Accept);
 68	            self.current_seq_num = accsync.seq_num;
 69	            let cached_idx = self.outgoing.len();
 70	            self.latest_accepted_meta = Some((accsync.n, cached_idx));
 71	            self.outgoing.push(Message::SequencePaxos(PaxosMessage {
 72	                from: self.pid,
 73	                to: from,
 74	                msg: PaxosMsg::Accepted(accepted),
 75	            }));
 76	            #[cfg(feature = "unicache")]
 77	            self.internal_storage.set_unicache(accsync.unicache);
 78	        }
 79	    }
 80	
 81	    fn forward_buffered_proposals(&mut self) {
 82	        let proposals = std::mem::take(&mut self.buffered_proposals);
 83	        if !proposals.is_empty() {
 84	            self.forward_proposals(proposals);
 85	        }
 86	    }
 87	
 88	    pub(crate) fn handle_acceptdecide(&mut self, acc_dec: AcceptDecide<T>) {
 89	        if self.check_valid_ballot(acc_dec.n)
 90	            && self.state == (Role::Follower, Phase::Accept)
 91	            && self.handle_sequence_num(acc_dec.seq_num, acc_dec.n.pid) == MessageStatus::Expected
 92	        {
 93	            #[cfg(not(feature = "unicache"))]
 94	            let entries = acc_dec.entries;
 95	            #[cfg(feature = "unicache")]
 96	            let entries = self.internal_storage.decode_entries(acc_dec.entries);
 97	            let mut new_accepted_idx = self
 98	                .internal_storage
 99	                .append_entries_and_get_accepted_idx(entries)
100	                .expect(WRITE_ERROR_MSG);
101	            let flushed_after_decide =
102	                self.update_decided_idx_and_get_accepted_idx(acc_dec.decided_idx);
103	            if flushed_after_decide.is_some() {
104	                new_accepted_idx = flushed_after_decide;
105	            }
106	            if let Some(idx) = new_accepted_idx {
107	                self.reply_accepted(acc_dec.n, idx);
108	            }
109	        }
110	    }
111	
112	    pub(crate) fn handle_accept_stopsign(&mut self, acc_ss: AcceptStopSign) {
113	        if self.check_valid_ballot(acc_ss.n)
114	            && self.state == (Role::Follower, Phase::Accept)
115	            && self.handle_sequence_num(acc_ss.seq_num, acc_ss.n.pid) == MessageStatus::Expected
116	        {
117	            // Flush entries before appending stopsign. The accepted index is ignored here as
118	            // it will be updated when appending stopsign.
119	            let _ = self.internal_storage.flush_batch().expect(WRITE_ERROR_MSG);
120	            let new_accepted_idx = self
121	                .internal_storage
122	                .set_stopsign(Some(acc_ss.ss))
123	                .expect(WRITE_ERROR_MSG);
124	            self.reply_accepted(acc_ss.n, new_accepted_idx);
125	        }
126	    }
127	
128	    pub(crate) fn handle_decide(&mut self, dec: Decide) {
129	        if self.check_valid_ballot(dec.n)
130	            && self.state.1 == Phase::Accept
131	            && self.handle_sequence_num(dec.seq_num, dec.n.pid) == MessageStatus::Expected
132	        {
133	            let new_accepted_idx = self.update_decided_idx_and_get_accepted_idx(dec.decided_idx);
134	            if let Some(idx) = new_accepted_idx {
135	                self.reply_accepted(dec.n, idx);
136	            }
137	        }
138	    }
139	
140	    /// To maintain decided index <= accepted index, batched entries may be flushed.
141	    /// Returns `Some(new_accepted_idx)` if entries are flushed, otherwise `None`.
142	    fn update_decided_idx_and_get_accepted_idx(&mut self, new_decided_idx: usize) -> Option<usize> {
143	        if new_decided_idx <= self.internal_storage.get_decided_idx() {
144	            return None;
145	        }
146	        if new_decided_idx > self.internal_storage.get_accepted_idx() {
147	            let new_accepted_idx = self.internal_storage.flush_batch().expect(WRITE_ERROR_MSG);
148	            self.internal_storage
149	                .set_decided_idx(new_decided_idx.min(new_accepted_idx))
150	                .expect(WRITE_ERROR_MSG);
151	            Some(new_accepted_idx)
152	        } else {
153	            self.internal_storage
154	                .set_decided_idx(new_decided_idx)
155	                .expect(WRITE_ERROR_MSG);
156	            None
157	        }
158	    }
159	
160	    fn reply_accepted(&mut self, n: Ballot, accepted_idx: usize) {
161	        let latest_accepted = self.get_latest_accepted_message(n);
162	        match latest_accepted {
163	            Some(acc) => acc.accepted_idx = accepted_idx,
164	            None => {
165	                let accepted = Accepted { n, accepted_idx };
166	                let cached_idx = self.outgoing.len();
167	                self.latest_accepted_meta = Some((n, cached_idx));
168	                self.outgoing.push(Message::SequencePaxos(PaxosMessage {
169	                    from: self.pid,
170	                    to: n.pid,
171	                    msg: PaxosMsg::Accepted(accepted),
172	                }));
173	            }
174	        }
175	    }
176	
177	    fn get_latest_accepted_message(&mut self, n: Ballot) -> Option<&mut Accepted> {
178	        if let Some((ballot, outgoing_idx)) = &self.latest_accepted_meta {
179	            if *ballot == n {
180	                if let Message::SequencePaxos(PaxosMessage {
181	                    msg: PaxosMsg::Accepted(a),
182	                    ..
183	                }) = self.outgoing.get_mut(*outgoing_idx).unwrap()
184	                {
185	                    return Some(a);
186	                } else {
187	                    #[cfg(feature = "logging")]
188	                    debug!(self.logger, "Cached idx is not an Accepted message!");
189	                }
190	            }
191	        }
192	        None
193	    }
194	
195	    /// Also returns whether the message's ballot was promised
196	    fn check_valid_ballot(&mut self, message_ballot: Ballot) -> bool {
197	        let my_promise = self.internal_storage.get_promise();
198	        match my_promise.cmp(&message_ballot) {
199	            std::cmp::Ordering::Equal => true,
200	            std::cmp::Ordering::Greater => {
201	                let not_acc = NotAccepted { n: my_promise };
202	                #[cfg(feature = "logging")]
203	                trace!(
204	                    self.logger,
205	                    "NotAccepted. My promise: {:?}, theirs: {:?}",
206	                    my_promise,
207	                    message_ballot
208	                );
209	                self.outgoing.push(Message::SequencePaxos(PaxosMessage {
210	                    from: self.pid,
211	                    to: message_ballot.pid,
212	                    msg: PaxosMsg::NotAccepted(not_acc),
213	                }));
214	                false
215	            }
216	            std::cmp::Ordering::Less => {
217	                // Should never happen, but to be safe send PrepareReq
218	                #[cfg(feature = "logging")]
219	                warn!(
220	                    self.logger,
221	                    "Received non-prepare message from a leader I've never promised. My: {:?}, theirs: {:?}", my_promise, message_ballot
222	                );
223	                self.reconnected(message_ballot.pid);
224	                false
225	            }
226	        }
227	    }
228	
229	    /// Also returns the MessageStatus of the sequence based on the incoming sequence number.
230	    fn handle_sequence_num(&mut self, seq_num: SequenceNumber, from: NodeId) -> MessageStatus {
231	        let msg_status = self.current_seq_num.check_msg_status(seq_num);
232	        match msg_status {
233	            MessageStatus::Expected => self.current_seq_num = seq_num,
234	            MessageStatus::DroppedPreceding => self.reconnected(from),
235	            MessageStatus::Outdated => (),
236	        };
237	        msg_status
238	    }
239	
240	    pub(crate) fn resend_messages_follower(&mut self) {
241	        match self.state.1 {
242	            Phase::Prepare => {
243	                // Resend Promise
244	                match &self.cached_promise_message {
245	                    Some(promise) => {
246	                        self.outgoing.push(Message::SequencePaxos(PaxosMessage {
247	                            from: self.pid,
248	                            to: promise.n.pid,
249	                            msg: PaxosMsg::Promise(promise.clone()),
250	                        }));
251	                    }
252	                    None => {
253	                        // Shouldn't be possible to be in prepare phase without having
254	                        // cached the promise sent as a response to the prepare
255	                        #[cfg(feature = "logging")]
256	                        warn!(self.logger, "In Prepare phase without a cached promise!");
257	                        self.state = (Role::Follower, Phase::Recover);
258	                        self.send_preparereq_to_all_peers();
259	                    }
260	                }
261	            }
262	            Phase::Recover => {
263	                // Resend PrepareReq
264	                self.send_preparereq_to_all_peers();
265	            }
266	            Phase::Accept => (),
267	            Phase::None => (),
268	        }
269	    }
270	
271	    fn send_preparereq_to_all_peers(&mut self) {
272	        let prepreq = PrepareReq {
273	            n: self.get_promise(),
274	        };
275	        for peer in &self.peers {
276	            self.outgoing.push(Message::SequencePaxos(PaxosMessage {
277	                from: self.pid,
278	                to: *peer,
279	                msg: PaxosMsg::PrepareReq(prepreq),
280	            }));
281	        }
282	    }
283	
284	    pub(crate) fn flush_batch_follower(&mut self) {
285	        let accepted_idx = self.internal_storage.get_accepted_idx();
286	        let new_accepted_idx = self.internal_storage.flush_batch().expect(WRITE_ERROR_MSG);
287	        if new_accepted_idx > accepted_idx {
288	            self.reply_accepted(self.get_promise(), new_accepted_idx);
289	        }
290	    }
