 36	impl PartialOrd for PromiseMetaData {
 37	    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
 38	        let ordering = if self.n_accepted == other.n_accepted
 39	            && self.accepted_idx == other.accepted_idx
 40	            && self.pid == other.pid
 41	        {
 42	            Ordering::Equal
 43	        } else if self.n_accepted > other.n_accepted
 44	            || (self.n_accepted == other.n_accepted && self.accepted_idx > other.accepted_idx)
 45	        {
 46	            Ordering::Greater
 47	        } else {
 48	            Ordering::Less
 49	        };
 50	        Some(ordering)
 51	    }
 52	}
 53	
 54	impl PartialEq for PromiseMetaData {
 55	    fn eq(&self, other: &Self) -> bool {
 56	        self.n_accepted == other.n_accepted
 57	            && self.accepted_idx == other.accepted_idx
 58	            && self.pid == other.pid
 59	    }
 60	}
