 73	#[derive(Debug, Clone)]
 74	pub(crate) struct LeaderState<T>
 75	where
 76	    T: Entry,
 77	{
 78	    pub n_leader: Ballot,
 79	    promises_meta: Vec<PromiseState>,
 80	    // the sequence number of accepts for each follower where AcceptSync has sequence number = 1
 81	    follower_seq_nums: Vec<SequenceNumber>,
 82	    pub accepted_indexes: Vec<usize>,
