 92	impl<T> LeaderState<T>
 93	where
 94	    T: Entry,
 95	{
 96	    pub fn with(n_leader: Ballot, max_pid: usize, quorum: Quorum) -> Self {
 97	        Self {
 98	            n_leader,
 99	            promises_meta: vec![PromiseState::NotPromised; max_pid],
100	            follower_seq_nums: vec![SequenceNumber::default(); max_pid],
101	            accepted_indexes: vec![0; max_pid],
102	            max_promise_meta: PromiseMetaData::default(),
103	            max_promise_sync: None,
104	            latest_accept_meta: vec![None; max_pid],
105	            max_pid,
106	            quorum,
107	        }
108	    }
109	
110	    fn pid_to_idx(pid: NodeId) -> usize {
111	        (pid - 1) as usize
112	    }
113	
114	    // Resets `pid`'s accept sequence to indicate they are in the next session of accepts
115	    pub fn increment_seq_num_session(&mut self, pid: NodeId) {
116	        let idx = Self::pid_to_idx(pid);
117	        self.follower_seq_nums[idx].session += 1;
118	        self.follower_seq_nums[idx].counter = 0;
119	    }
120	
121	    pub fn next_seq_num(&mut self, pid: NodeId) -> SequenceNumber {
122	        let idx = Self::pid_to_idx(pid);
123	        self.follower_seq_nums[idx].counter += 1;
124	        self.follower_seq_nums[idx]
125	    }
126	
127	    pub fn get_seq_num(&mut self, pid: NodeId) -> SequenceNumber {
128	        self.follower_seq_nums[Self::pid_to_idx(pid)]
129	    }
130	
131	    pub fn set_promise(&mut self, prom: Promise<T>, from: NodeId, check_max_prom: bool) -> bool {
132	        let promise_meta = PromiseMetaData {
133	            n_accepted: prom.n_accepted,
134	            accepted_idx: prom.accepted_idx,
135	            decided_idx: prom.decided_idx,
136	            pid: from,
137	        };
138	        if check_max_prom && promise_meta > self.max_promise_meta {
139	            self.max_promise_meta = promise_meta.clone();
140	            self.max_promise_sync = prom.log_sync;
141	        }
142	        self.promises_meta[Self::pid_to_idx(from)] = PromiseState::Promised(promise_meta);
143	        let num_promised = self
144	            .promises_meta
145	            .iter()
146	            .filter(|p| matches!(p, PromiseState::Promised(_)))
147	            .count();
148	        self.quorum.is_prepare_quorum(num_promised)
149	    }
150	
151	    pub fn reset_promise(&mut self, pid: NodeId) {
152	        self.promises_meta[Self::pid_to_idx(pid)] = PromiseState::NotPromised;
153	    }
154	
155	    /// Node `pid` seen with ballot greater than my ballot
156	    pub fn lost_promise(&mut self, pid: NodeId) {
157	        self.promises_meta[Self::pid_to_idx(pid)] = PromiseState::PromisedHigher;
158	    }
159	
160	    pub fn take_max_promise_sync(&mut self) -> Option<LogSync<T>> {
161	        std::mem::take(&mut self.max_promise_sync)
162	    }
163	
164	    pub fn get_max_promise_meta(&self) -> &PromiseMetaData {
165	        &self.max_promise_meta
166	    }
167	
168	    pub fn get_max_decided_idx(&self) -> usize {
169	        self.promises_meta
170	            .iter()
171	            .filter_map(|p| match p {
172	                PromiseState::Promised(m) => Some(m.decided_idx),
173	                _ => None,
174	            })
175	            .max()
176	            .unwrap_or_default()
177	    }
178	
179	    pub fn get_promise_meta(&self, pid: NodeId) -> &PromiseMetaData {
180	        match &self.promises_meta[Self::pid_to_idx(pid)] {
181	            PromiseState::Promised(metadata) => metadata,
182	            _ => panic!("No Metadata found for promised follower"),
183	        }
184	    }
185	
186	    pub fn get_min_all_accepted_idx(&self) -> &usize {
187	        self.accepted_indexes
188	            .iter()
189	            .min()
190	            .expect("Should be all initialised to 0!")
191	    }
192	
193	    pub fn reset_latest_accept_meta(&mut self) {
194	        self.latest_accept_meta = vec![None; self.max_pid];
195	    }
196	
197	    pub fn get_promised_followers(&self) -> Vec<NodeId> {
198	        self.promises_meta
199	            .iter()
200	            .enumerate()
201	            .filter_map(|(idx, x)| match x {
202	                PromiseState::Promised(_) if idx != Self::pid_to_idx(self.n_leader.pid) => {
203	                    Some((idx + 1) as NodeId)
204	                }
205	                _ => None,
206	            })
207	            .collect()
208	    }
209	
210	    /// The pids of peers which have not promised a higher ballot than mine.
211	    pub(crate) fn get_preparable_peers(&self, peers: &[NodeId]) -> Vec<NodeId> {
212	        peers
213	            .iter()
214	            .filter_map(|pid| {
215	                let idx = Self::pid_to_idx(*pid);
216	                match self.promises_meta.get(idx).unwrap() {
217	                    PromiseState::NotPromised => Some(*pid),
218	                    _ => None,
219	                }
220	            })
221	            .collect()
222	    }
223	
224	    pub fn set_latest_accept_meta(&mut self, pid: NodeId, idx: Option<usize>) {
225	        let meta = idx.map(|x| (self.n_leader, x));
226	        self.latest_accept_meta[Self::pid_to_idx(pid)] = meta;
227	    }
228	
229	    pub fn set_accepted_idx(&mut self, pid: NodeId, idx: usize) {
230	        self.accepted_indexes[Self::pid_to_idx(pid)] = idx;
231	    }
232	
233	    pub fn get_latest_accept_meta(&self, pid: NodeId) -> Option<(Ballot, usize)> {
234	        self.latest_accept_meta
235	            .get(Self::pid_to_idx(pid))
236	            .unwrap()
237	            .as_ref()
238	            .copied()
239	    }
240	
241	    pub fn get_decided_idx(&self, pid: NodeId) -> Option<usize> {
242	        match self.promises_meta.get(Self::pid_to_idx(pid)).unwrap() {
243	            PromiseState::Promised(metadata) => Some(metadata.decided_idx),
244	            _ => None,
245	        }
246	    }
247	
248	    pub fn get_accepted_idx(&self, pid: NodeId) -> usize {
249	        *self.accepted_indexes.get(Self::pid_to_idx(pid)).unwrap()
250	    }
251	
252	    pub fn is_chosen(&self, idx: usize) -> bool {
253	        let num_accepted = self
254	            .accepted_indexes
255	            .iter()
256	            .filter(|la| **la >= idx)
257	            .count();
258	        self.quorum.is_accept_quorum(num_accepted)
259	    }
260	}
