263	#[derive(Debug, Clone)]
264	pub enum LogEntry<T>
265	where
266	    T: Entry,
267	{
268	    /// The entry is decided.
269	    Decided(T),
270	    /// The entry is NOT decided. Might be removed from the log at a later time.
271	    Undecided(T),
272	    /// The entry has been trimmed.
273	    Trimmed(TrimmedIndex),
274	    /// The entry has been snapshotted.
275	    Snapshotted(SnapshottedEntry<T>),
276	    /// This Sequence Paxos instance has been stopped for reconfiguration. The accompanying bool
277	    /// indicates whether the reconfiguration has been decided or not. If it is `true`, then the OmniPaxos instance for the new configuration can be started.
278	    StopSign(StopSign, bool),
279	}
