281	impl<T: PartialEq + Entry> PartialEq for LogEntry<T>
282	where
283	    <T as Entry>::Snapshot: PartialEq,
284	{
285	    fn eq(&self, other: &Self) -> bool {
286	        match (self, other) {
287	            (LogEntry::Decided(v1), LogEntry::Decided(v2)) => v1 == v2,
288	            (LogEntry::Undecided(v1), LogEntry::Undecided(v2)) => v1 == v2,
289	            (LogEntry::Trimmed(idx1), LogEntry::Trimmed(idx2)) => idx1 == idx2,
290	            (LogEntry::Snapshotted(s1), LogEntry::Snapshotted(s2)) => s1 == s2,
291	            (LogEntry::StopSign(ss1, b1), LogEntry::StopSign(ss2, b2)) => ss1 == ss2 && b1 == b2,
292	            _ => false,
293	        }
294	    }
295	}
