360	#[derive(PartialEq, Eq)]
361	pub(crate) enum MessageStatus {
362	    /// Expected message sequence progression
363	    Expected,
364	    /// Identified a message sequence break
365	    DroppedPreceding,
366	    /// An already identified message sequence break
367	    Outdated,
