370	/// Keeps track of the ordering of messages in the accept phase
371	#[derive(Copy, Clone, Debug, Default, PartialEq, Eq, PartialOrd, Ord)]
372	#[cfg_attr(feature = "serde", derive(Serialize, Deserialize))]
373	pub struct SequenceNumber {
374	    /// Meant to refer to a TCP session
375	    pub session: u64,
376	    /// The sequence number with respect to a session
377	    pub counter: u64,
378	}
379	
380	impl SequenceNumber {
381	    /// Compares this sequence number with the sequence number of an incoming message.
382	    pub(crate) fn check_msg_status(&self, msg_seq_num: SequenceNumber) -> MessageStatus {
383	        if msg_seq_num.session == self.session && msg_seq_num.counter == self.counter + 1 {
384	            MessageStatus::Expected
385	        } else if msg_seq_num <= *self {
386	            MessageStatus::Outdated
387	        } else {
388	            MessageStatus::DroppedPreceding
389	        }
390	    }
391	}
