414	/// Flexible quorums can be used to increase/decrease the read and write quorum sizes,
415	/// for different latency vs fault tolerance tradeoffs.
416	#[derive(Copy, Clone, Debug, PartialEq, Eq)]
417	#[cfg_attr(any(feature = "serde", feature = "toml_config"), derive(Deserialize))]
418	#[cfg_attr(feature = "serde", derive(Serialize))]
419	pub struct FlexibleQuorum {
420	    /// The number of nodes a leader needs to consult to get an up-to-date view of the log.
421	    pub read_quorum_size: usize,
422	    /// The number of acknowledgments a leader needs to commit an entry to the log
423	    pub write_quorum_size: usize,
424	}
