426	/// The type of quorum used by the OmniPaxos cluster.
427	#[derive(Copy, Clone, Debug)]
428	pub(crate) enum Quorum {
429	    /// Both the read quorum and the write quorums are a majority of nodes
430	    Majority(usize),
431	    /// The read and write quorum sizes are defined by a `FlexibleQuorum`
432	    Flexible(FlexibleQuorum),
433	}
434	
435	impl Quorum {
436	    pub(crate) fn with(flexible_quorum_config: Option<FlexibleQuorum>, num_nodes: usize) -> Self {
437	        match flexible_quorum_config {
438	            Some(FlexibleQuorum {
439	                read_quorum_size,
440	                write_quorum_size,
441	            }) => Quorum::Flexible(FlexibleQuorum {
442	                read_quorum_size,
443	                write_quorum_size,
444	            }),
445	            None => Quorum::Majority(num_nodes / 2 + 1),
446	        }
447	    }
448	
449	    pub(crate) fn is_prepare_quorum(&self, num_nodes: usize) -> bool {
450	        match self {
451	            Quorum::Majority(majority) => num_nodes >= *majority,
452	            Quorum::Flexible(flex_quorum) => num_nodes >= flex_quorum.read_quorum_size,
453	        }
454	    }
455	
456	    pub(crate) fn is_accept_quorum(&self, num_nodes: usize) -> bool {
457	        match self {
458	            Quorum::Majority(majority) => num_nodes >= *majority,
459	            Quorum::Flexible(flex_quorum) => num_nodes >= flex_quorum.write_quorum_size,
460	        }
461	    }
462	}
