119	                "Read quorum must be in range 2 to # of nodes in the cluster"
120	            );
121	            valid_config!(
122	                write_quorum_size >= 2 && write_quorum_size <= num_nodes,
123	                "Write quorum must be in range 2 to # of nodes in the cluster"
124	            );
