400	    /// Increments the internal logical clock. This drives the processes for leader changes, resending dropped messages, and flushing batched log entries.
401	    /// Each of these is triggered every `election_tick_timeout`, `resend_message_tick_timeout`, and `flush_batch_tick_timeout` number of calls to this function
402	    /// (See how to configure these timeouts in `ServerConfig`).
403	    pub fn tick(&mut self) {
404	        if self.election_clock.tick_and_check_timeout() {
405	            self.election_timeout();
406	        }
407	        if self.resend_message_clock.tick_and_check_timeout() {
408	            self.seq_paxos.resend_message_timeout();
409	        }
410	        if self.flush_batch_clock.tick_and_check_timeout() {
411	            self.seq_paxos.flush_batch_timeout();
412	        }
413	    }
