 55	    fn load_cache(&mut self) {
 56	        self.state_cache.promise = self
 57	            .storage
 58	            .get_promise()
 59	            .expect("Failed to load cache from storage.")
 60	            .unwrap_or_default();
 61	        self.state_cache.decided_idx = self.storage.get_decided_idx().unwrap();
 62	        self.state_cache.accepted_round = self
 63	            .storage
 64	            .get_accepted_round()
 65	            .unwrap()
 66	            .unwrap_or_default();
 67	        self.state_cache.compacted_idx = self.storage.get_compacted_idx().unwrap();
 68	        self.state_cache.stopsign = self.storage.get_stopsign().unwrap();
 69	        self.state_cache.accepted_idx =
 70	            self.storage.get_log_len().unwrap() + self.state_cache.compacted_idx;
 71	        if self.state_cache.stopsign.is_some() {
 72	            self.state_cache.accepted_idx += 1;
 73	        }
