 76	    /// Read all decided entries from `from_idx` in the log. Returns `None` if `from_idx` is out of bounds.
 77	    pub(crate) fn read_decided_suffix(
 78	        &self,
 79	        from_idx: usize,
 80	    ) -> StorageResult<Option<Vec<LogEntry<T>>>> {
 81	        let decided_idx = self.get_decided_idx();
 82	        if from_idx < decided_idx {
 83	            self.read(from_idx..decided_idx)
 84	        } else {
 85	            Ok(None)
 86	        }
 87	    }
 88	
 89	    /// Read entries in the range `r` in the log. Returns `None` if `r` is out of bounds.
 90	    pub(crate) fn read<R>(&self, r: R) -> StorageResult<Option<Vec<LogEntry<T>>>>
 91	    where
 92	        R: RangeBounds<usize>,
 93	    {
 94	        let from_idx = match r.start_bound() {
 95	            Bound::Included(i) => *i,
 96	            Bound::Excluded(e) => *e + 1,
 97	            Bound::Unbounded => 0,
 98	        };
 99	        let to_idx = match r.end_bound() {
100	            Bound::Included(i) => *i + 1,
101	            Bound::Excluded(e) => *e,
102	            Bound::Unbounded => self.get_accepted_idx(),
103	        };
104	        if to_idx == 0 {
105	            return Ok(None);
106	        }
107	        let compacted_idx = self.get_compacted_idx();
108	        let accepted_idx = self.get_accepted_idx();
109	        // use to_idx-1 when getting the entry type as to_idx is exclusive
110	        let to_type = match self.get_entry_type(to_idx - 1, compacted_idx, accepted_idx)? {
111	            Some(IndexEntry::Compacted) => {
112	                return Ok(Some(vec![self.create_compacted_entry(compacted_idx)?]))
113	            }
114	            Some(from_type) => from_type,
115	            _ => return Ok(None),
116	        };
117	        let from_type = match self.get_entry_type(from_idx, compacted_idx, accepted_idx)? {
118	            Some(from_type) => from_type,
119	            _ => return Ok(None),
120	        };
121	        match (from_type, to_type) {
122	            (IndexEntry::Entry, IndexEntry::Entry) => {
123	                Ok(Some(self.create_read_log_entries(from_idx, to_idx)?))
124	            }
125	            (IndexEntry::Entry, IndexEntry::StopSign(ss)) => {
126	                let mut entries = self.create_read_log_entries(from_idx, to_idx - 1)?;
127	                entries.push(LogEntry::StopSign(ss, self.stopsign_is_decided()));
128	                Ok(Some(entries))
129	            }
130	            (IndexEntry::Compacted, IndexEntry::Entry) => {
131	                let mut entries = Vec::with_capacity(to_idx - compacted_idx + 1);
132	                let compacted = self.create_compacted_entry(compacted_idx)?;
133	                entries.push(compacted);
134	                let mut e = self.create_read_log_entries(compacted_idx, to_idx)?;
135	                entries.append(&mut e);
136	                Ok(Some(entries))
137	            }
138	            (IndexEntry::Compacted, IndexEntry::StopSign(ss)) => {
139	                let mut entries = Vec::with_capacity(to_idx - compacted_idx + 1);
140	                let compacted = self.create_compacted_entry(compacted_idx)?;
141	                entries.push(compacted);
142	                let mut e = self.create_read_log_entries(compacted_idx, to_idx - 1)?;
143	                entries.append(&mut e);
144	                entries.push(LogEntry::StopSign(ss, self.stopsign_is_decided()));
145	                Ok(Some(entries))
146	            }
147	            (IndexEntry::StopSign(ss), IndexEntry::StopSign(_)) => {
148	                Ok(Some(vec![LogEntry::StopSign(
149	                    ss,
150	                    self.stopsign_is_decided(),
151	                )]))
152	            }
153	            e => {
154	                unimplemented!("{}", format!("Unexpected read combination: {:?}", e))
155	            }
156	        }
157	    }
158	
159	    fn get_entry_type(
160	        &self,
161	        idx: usize,
162	        compacted_idx: usize,
163	        accepted_idx: usize,
164	    ) -> StorageResult<Option<IndexEntry>> {
165	        if idx < compacted_idx {
166	            Ok(Some(IndexEntry::Compacted))
167	        } else if idx + 1 < accepted_idx {
168	            Ok(Some(IndexEntry::Entry))
169	        } else if idx + 1 == accepted_idx {
170	            match self.get_stopsign() {
171	                Some(ss) => Ok(Some(IndexEntry::StopSign(ss))),
172	                _ => Ok(Some(IndexEntry::Entry)),
173	            }
174	        } else {
175	            Ok(None)
176	        }
177	    }
178	
179	    fn create_read_log_entries(&self, from: usize, to: usize) -> StorageResult<Vec<LogEntry<T>>> {
180	        let decided_idx = self.get_decided_idx();
181	        let entries = self
182	            .get_entries(from, to)?
183	            .into_iter()
184	            .enumerate()
185	            .map(|(idx, e)| {
186	                let log_idx = idx + from;
187	                if log_idx < decided_idx {
188	                    LogEntry::Decided(e)
189	                } else {
190	                    LogEntry::Undecided(e)
191	                }
192	            })
193	            .collect();
194	        Ok(entries)
195	    }
196	
197	    fn create_compacted_entry(&self, compacted_idx: usize) -> StorageResult<LogEntry<T>> {
198	        self.storage.get_snapshot().map(|snap| match snap {
199	            Some(s) => LogEntry::Snapshotted(SnapshottedEntry::with(compacted_idx, s)),
200	            None => LogEntry::Trimmed(compacted_idx),
201	        })
202	    }
