237	    fn flush_if_full_batch(
238	        &mut self,
239	        append_res: Option<Vec<T>>,
240	    ) -> StorageResult<Option<AcceptedMetaData<T>>> {
241	        if let Some(flushed_entries) = append_res {
242	            let accepted_idx = self.append_entries_without_batching(flushed_entries.clone())?;
243	            Ok(Some(AcceptedMetaData {
244	                accepted_idx,
245	                #[cfg(not(feature = "unicache"))]
246	                entries: flushed_entries,
247	                #[cfg(feature = "unicache")]
248	                entries: self.state_cache.take_batched_processed(),
249	            }))
250	        } else {
251	            Ok(None)
252	        }
253	    }
