313	    pub(crate) fn sync_log(
314	        &mut self,
315	        accepted_round: Ballot,
316	        decided_idx: usize,
317	        log_sync: Option<LogSync<T>>,
318	    ) -> StorageResult<usize> {
319	        self.state_cache.accepted_round = accepted_round;
320	        self.state_cache.decided_idx = decided_idx;
321	        let mut sync_txn: Vec<StorageOp<T>> = vec![
322	            StorageOp::SetAcceptedRound(accepted_round),
323	            StorageOp::SetDecidedIndex(decided_idx),
324	        ];
325	        if let Some(sync) = log_sync {
326	            match sync.decided_snapshot {
327	                Some(SnapshotType::Complete(c)) => {
328	                    self.state_cache.compacted_idx = sync.sync_idx;
329	                    sync_txn.push(StorageOp::Trim(sync.sync_idx));
330	                    sync_txn.push(StorageOp::SetCompactedIdx(sync.sync_idx));
331	                    sync_txn.push(StorageOp::SetSnapshot(Some(c)));
332	                }
333	                Some(SnapshotType::Delta(d)) => {
334	                    let mut snapshot = self.create_decided_snapshot()?;
335	                    snapshot.merge(d);
336	                    self.state_cache.compacted_idx = sync.sync_idx;
337	                    sync_txn.push(StorageOp::Trim(sync.sync_idx));
338	                    sync_txn.push(StorageOp::SetCompactedIdx(sync.sync_idx));
339	                    sync_txn.push(StorageOp::SetSnapshot(Some(snapshot)));
340	                }
341	                None => (),
342	            }
343	            self.state_cache.accepted_idx = sync.sync_idx + sync.suffix.len();
344	            sync_txn.push(StorageOp::AppendOnPrefix(sync.sync_idx, sync.suffix));
345	            match sync.stopsign {
346	                Some(ss) => {
347	                    self.state_cache.stopsign = Some(ss.clone());
348	                    self.state_cache.accepted_idx += 1;
349	                    sync_txn.push(StorageOp::SetStopsign(Some(ss)));
350	                }
351	                None if self.state_cache.stopsign.is_some() => {
