367	    pub(crate) fn create_snapshot(&self, compact_idx: usize) -> StorageResult<T::Snapshot> {
368	        let current_compacted_idx = self.get_compacted_idx();
369	        if compact_idx < current_compacted_idx {
370	            Err(CompactionErr::TrimmedIndex(current_compacted_idx))?
371	        }
372	        let entries = self
373	            .storage
374	            .get_entries(current_compacted_idx, compact_idx)?;
375	        let delta = T::Snapshot::create(entries.as_slice());
376	        match self.storage.get_snapshot()? {
377	            Some(mut s) => {
378	                s.merge(delta);
379	                Ok(s)
380	            }
381	            None => Ok(delta),
382	        }
383	    }
