385	    // Creates a Delta snapshot of entries from `from_idx` to the end of the decided log and also
386	    // returns the compacted idx of the created snapshot. If the range of entries contains entries
387	    // which have already been compacted a valid delta cannot be created, so creates a Complete
388	    // snapshot of the entire decided log instead.
389	    pub(crate) fn create_diff_snapshot(
390	        &self,
391	        from_idx: usize,
392	    ) -> StorageResult<(Option<SnapshotType<T>>, usize)> {
393	        let log_decided_idx = self.get_decided_idx_without_stopsign();
394	        let compacted_idx = self.get_compacted_idx();
395	        let snapshot = if from_idx <= compacted_idx {
396	            // Some entries in range are compacted, snapshot entire decided log
397	            if compacted_idx < log_decided_idx {
398	                Some(SnapshotType::Complete(
399	                    self.create_snapshot(log_decided_idx)?,
400	                ))
401	            } else {
402	                // Entire decided log already snapshotted
403	                self.get_snapshot()?.map(|s| SnapshotType::Complete(s))
404	            }
405	        } else {
406	            let diff_entries = self.get_entries(from_idx, log_decided_idx)?;
407	            Some(SnapshotType::Delta(T::Snapshot::create(
408	                diff_entries.as_slice(),
409	            )))
410	        };
411	        Ok((snapshot, log_decided_idx))
412	    }
