414	    pub(crate) fn try_trim(&mut self, idx: usize) -> StorageResult<()> {
415	        let decided_idx = self.get_decided_idx();
416	        let log_decided_idx = self.get_decided_idx_without_stopsign();
417	        let new_compacted_idx = match idx.cmp(&decided_idx) {
418	            Ordering::Less => idx,
419	            Ordering::Equal => log_decided_idx,
420	            Ordering::Greater => Err(CompactionErr::UndecidedIndex(decided_idx))?,
421	        };
422	        if new_compacted_idx > self.get_compacted_idx() {
423	            self.storage.write_atomically(vec![
424	                StorageOp::Trim(new_compacted_idx),
425	                StorageOp::SetCompactedIdx(new_compacted_idx),
426	            ])?;
427	            self.state_cache.compacted_idx = new_compacted_idx;
428	        }
429	        Ok(())
430	    }
