432	    pub(crate) fn try_snapshot(&mut self, snapshot_idx: Option<usize>) -> StorageResult<()> {
433	        let decided_idx = self.get_decided_idx();
434	        let log_decided_idx = self.get_decided_idx_without_stopsign();
435	        let new_compacted_idx = match snapshot_idx {
436	            Some(i) => match i.cmp(&decided_idx) {
437	                Ordering::Less => i,
438	                Ordering::Equal => log_decided_idx,
439	                Ordering::Greater => Err(CompactionErr::UndecidedIndex(decided_idx))?,
440	            },
441	            None => log_decided_idx,
442	        };
443	        if new_compacted_idx > self.get_compacted_idx() {
444	            let snapshot = self.create_snapshot(new_compacted_idx)?;
445	            self.storage.write_atomically(vec![
446	                StorageOp::Trim(new_compacted_idx),
447	                StorageOp::SetCompactedIdx(new_compacted_idx),
448	                StorageOp::SetSnapshot(Some(snapshot)),
449	            ])?;
450	            self.state_cache.compacted_idx = new_compacted_idx;
451	        }
452	        Ok(())
453	    }
