    60	        }
    61	    }
    62	
    63	    // Appends an entry to the end of the `batched_entries`. If the batch is full, the
    64	    // batch is flushed and return flushed entries. Else, return None.
    65	    pub(super) fn append_entry(&mut self, entry: T) -> Option<Vec<T>> {
    66	        #[cfg(feature = "unicache")]
    67	        {
    68	            let processed = self.unicache.try_encode(&entry);
    69	            self.batched_processed_by_leader.push(processed);
    70	        }
    71	        self.batched_entries.push(entry);
    72	        self.take_entries_if_batch_is_full()
    73	    }
    74	
    75	    // Appends entries to the end of the `batched_entries`. If the batch is full, the
    76	    // batch is flushed and return flushed entries. Else, return None.
    77	    pub(super) fn append_entries(&mut self, entries: Vec<T>) -> Option<Vec<T>> {
    78	        #[cfg(feature = "unicache")]
    79	        {
    80	            if self.promise.pid == self.pid {
    81	                // only try encoding if we're the leader
    82	                for entry in &entries {
    83	                    let processed = self.unicache.try_encode(entry);
    84	                    self.batched_processed_by_leader.push(processed);
    85	                }
    86	            }
    87	        }
    88	        self.batched_entries.extend(entries);
    89	        self.take_entries_if_batch_is_full()
    90	    }
