   103	    // Return batched entries if the batch is full that need to be flushed in to storage.
   104	    fn take_entries_if_batch_is_full(&mut self) -> Option<Vec<T>> {
   105	        if self.batched_entries.len() >= self.batch_size {
   106	            Some(self.take_batched_entries())
   107	        } else {
   108	            None
   109	        }
   110	    }
