221	        }
222	    }
223	
224	    /// Effective cap for `outgoing_buf`: the channel's own capacity when known,
225	    /// else [`ActorConfig::max_outgoing_buffered`].
226	    fn outgoing_buf_cap(&self) -> usize {
227	        self.outgoing_tx
228	            .capacity()
229	            .unwrap_or(self.config.max_outgoing_buffered)
230	    }
231	
232	    /// Non-blocking drain of `outgoing_buf` onto `outgoing_tx`. Uses `try_send`
233	    /// so a merely-full channel (slow consumer) doesn't block the actor loop;
234	    /// unsent messages stay in `outgoing_buf` (in order) for the next attempt.
235	    /// If the buffer exceeds [`Self::outgoing_buf_cap`], oldest messages are
236	    /// dropped — see [`RuntimeConfig::max_outgoing_buffered`].
237	    fn drain_outgoing_buf(&mut self) {
238	        let cap = self.outgoing_buf_cap();
239	        trim_oldest(&mut self.outgoing_buf, cap);
240	
241	        let pending = std::mem::take(&mut self.outgoing_buf);
242	        let mut iter = pending.into_iter();
243	        for msg in iter.by_ref() {
244	            match self.outgoing_tx.try_send(msg) {
245	                Ok(()) => {}
246	                Err(async_channel::TrySendError::Full(msg)) => {
247	                    self.outgoing_buf.push(msg);
248	                    break;
249	                }
250	                Err(async_channel::TrySendError::Closed(_)) => {
251	                    // Receiver dropped — user is not draining outgoing. Discard
252	                    // everything remaining; nothing left to retry against.
253	                    return;
254	                }
255	            }
256	        }
257	        self.outgoing_buf.extend(iter);
258	    }
259	
260	    /// Enqueue one outgoing message without awaiting. Appends behind any
261	    /// already-buffered messages (preserves order), then tries to drain.
262	    /// Used for both core protocol traffic (via [`Self::flush_outgoing`]) and
263	    /// runtime control-plane messages (`TaggedProposal` / `Assigned`).
264	    fn enqueue_outgoing(&mut self, msg: Message<T>) {
265	        self.outgoing_buf.push(msg);
266	        self.drain_outgoing_buf();
267	    }
268	
269	    /// Pull newly-produced OmniPaxos/BLE messages into `outgoing_buf` and drain.
270	    fn flush_outgoing(&mut self) {
271	        self.op.take_outgoing_messages(&mut self.outgoing_buf);
272	        self.drain_outgoing_buf();
273	    }
274	
275	    /// Push newly-decided entries to a single, freshly-added subscriber. Used
276	    /// only on the immediate catch-up path from `Command::SubscribeDecided`,
277	    /// where there is no shared read to amortize against. Returns `false` if
278	    /// the receiver was already closed.
279	    fn push_to_sub(op: &mut OmniPaxos<T, B>, sub: &mut DecidedSub<T>) -> bool {
280	        let decided = op.get_decided_idx();
281	        if sub.next_idx >= decided {
282	            return true;
283	        }
284	        let Some(entries) = op.read_decided_suffix(sub.next_idx) else {
285	            return true;
286	        };
287	        for entry in entries {
288	            match sub.tx.try_send(entry) {
289	                Ok(()) => sub.next_idx += 1,
290	                Err(async_channel::TrySendError::Full(_)) => return true,
291	                Err(async_channel::TrySendError::Closed(_)) => return false,
292	            }
293	        }
294	        true
295	    }
296	
297	    /// Push newly-decided entries to every subscriber, reading the log suffix
298	    /// **once** and fanning out. Each sub keeps its own cursor, so slow subs
299	    /// don't block fast ones; the storage read is amortized across all subs
300	    /// starting from the trailing sub's position.
301	    fn push_to_all_subs(&mut self) {
302	        if self.decided_subscribers.is_empty() {
303	            return;
304	        }
305	        let cur = self.op.get_decided_idx();
306	        let min_next = self
307	            .decided_subscribers
308	            .iter()
309	            .map(|s| s.next_idx)
310	            .min()
311	            .expect("non-empty checked above");
312	        if min_next >= cur {
313	            return;
314	        }
315	        // Read once, from the trailing sub's position. `entries[i]` is the log
316	        // entry at position `min_next + i`.
317	        let Some(entries) = self.op.read_decided_suffix(min_next) else {
318	            return;
319	        };
320	        // Fan out; drop closed subscribers in place via retain_mut.
321	        self.decided_subscribers.retain_mut(|sub| {
322	            // sub.next_idx should always be >= min_next; guard defensively.
323	            let start = sub.next_idx.saturating_sub(min_next);
324	            for entry in entries.iter().skip(start) {
325	                match sub.tx.try_send(entry.clone()) {
326	                    Ok(()) => sub.next_idx += 1,
327	                    Err(async_channel::TrySendError::Full(_)) => break,
328	                    Err(async_channel::TrySendError::Closed(_)) => return false,
329	                }
330	            }
331	            true
332	        });
333	    }
334	
335	    fn record_assignment(&mut self, id: EntryId, idx: usize, ballot: Ballot) {
336	        for p in self.pending.iter_mut() {
337	            if p.id == id {
338	                p.assigned = Some((idx, ballot));
339	                return;
340	            }
341	        }
342	        // No matching pending — late reply after timeout drain, or duplicate. Ignore.
343	    }
344	
345	    /// Resolves a pending `append_notify` immediately with the propose error that
346	    /// just failed it, instead of leaving it to silently time out. Only affects
347	    /// entries this node itself owns in `self.pending` — when `id` came from a
348	    /// remote `TaggedProposal`, the owning `Pending` lives on the origin node, so
349	    /// this is a no-op there and that call still resolves via `Timeout`.
350	    fn resolve_pending_failed(&mut self, id: EntryId, err: ProposeErr<T>) {
351	        if let Some(pos) = self.pending.iter().position(|p| p.id == id) {
352	            let p = self.pending.remove(pos).unwrap();
353	            let _ = p.reply.send(Err(AppendError::Propose(err)));
354	        }
355	    }
356	
357	    /// Appends `entry` to the local log, tracking it in `unconfirmed_local` if
358	    /// the write is genuinely deferred by batching (`get_batched_len()` grew)
359	    /// rather than immediately reflected in `get_accepted_idx()`. `intent`
360	    /// says what to do with the eventual index; plain `Command::Append` passes
361	    /// `TrackIntent::Untracked`.
362	    ///
363	    /// Must check `get_batched_len()` rather than inferring "batched" from
364	    /// `before == after`: a follower, or a leader still in `Phase::Prepare`,
365	    /// also has `before == after`, but the entry went to `buffered_proposals`
366	    /// or out as a `ProposalForward`, not the shared batch buffer — pushing a
367	    /// placeholder for that case would desync `unconfirmed_local`'s FIFO
368	    /// count. `accept_as_leader`'s stable-leader gate means only plain
369	    /// `Command::Append` can hit this case.
370	    fn append_tracked(
371	        &mut self,
372	        intent: TrackIntent,
373	        entry: T,
374	    ) -> Result<Option<(usize, Ballot)>, ProposeErr<T>> {
375	        let accepted_before = self.op.get_accepted_idx();
376	        let batched_before = self.op.get_batched_len();
377	        self.op.append(entry)?;
378	        let accepted_after = self.op.get_accepted_idx();
379	        let batched_after = self.op.get_batched_len();
380	        if accepted_after > accepted_before {
381	            let ballot = self.op.get_promise();
382	            if let TrackIntent::Local(id) = intent {
383	                self.record_assignment(id, accepted_after, ballot);
384	            }
385	            Ok(Some((accepted_after, ballot)))
386	        } else if batched_after > batched_before {
387	            // Genuinely deferred by batching.
388	            self.unconfirmed_local
389	                .push_back((intent, self.op.get_promise()));
390	            Ok(None)
391	        } else {
392	            // Went somewhere else entirely (forwarded, or buffered pending a
393	            // Prepare -> Accept transition) -- nothing entered the shared
394	            // batch buffer, so there's nothing to track here.
395	            Ok(None)
396	        }
397	    }
398	
399	    /// Leader-side accept, for an entry we originate locally (`from: None`)
400	    /// or received via `TaggedProposal` from follower `from`. Populates the
401	    /// pending's `assigned` (or, if buffered by batching, queues a
402	    /// `TrackIntent` for `reconcile_unconfirmed` to resolve later) and
403	    /// returns `(id, assigned_idx)` if accepted immediately, so batch callers
404	    /// can collect these and send one `Assigned` reply for the whole batch.
405	    fn accept_as_leader(
406	        &mut self,
407	        id: EntryId,
408	        entry: T,
409	        from: Option<NodeId>,
410	    ) -> Option<(EntryId, usize)> {
411	        // Only accept while leadership is stable (Accept phase).
412	        let stable_leader =
413	            matches!(self.op.get_current_leader(), Some((pid, true)) if pid == self.pid);
414	        if !stable_leader {
415	            return None;
416	        }
417	        let intent = match from {
418	            None => TrackIntent::Local(id),
419	            Some(from) => TrackIntent::Remote { id, from },
420	        };
421	        match self.append_tracked(intent, entry) {
422	            Ok(Some((after, _ballot))) => Some((id, after)),
423	            Ok(None) => None,
424	            Err(err) => {
425	                self.resolve_pending_failed(id, err);
426	                None
427	            }
428	        }
429	    }
430	
431	    /// Matches everything buffered in `unconfirmed_local` to the index it's
432	    /// assigned once its batch flushes and `get_accepted_idx()` advances.
433	    /// FIFO correspondence is exact here regardless of what added to the
434	    /// shared batch buffer (see `unconfirmed_local`'s doc comment), as long as
435	    /// the ballot hasn't changed since the entry was buffered; if it has,
436	    /// leadership moved on and this index may belong to different writes, so
437	    /// we drop tracking for it and let the caller time out.
438	    fn reconcile_unconfirmed(&mut self) {
439	        let cur_ballot = self.op.get_promise();
440	        let accepted = self.op.get_accepted_idx();
441	        let mut idx = self.last_seen_accepted_idx;
442	        // Entries from a single remote TaggedProposal batch can resolve
443	        // across several different `idx` values here (their own batch may
444	        // have been interleaved with others' writes); group by origin so
445	        // each gets one `Assigned` reply instead of one message per entry.
446	        let mut remote_assigned: HashMap<NodeId, Vec<(EntryId, usize)>> = HashMap::new();
447	        while idx < accepted {
448	            idx += 1;
449	            let Some((intent, ballot)) = self.unconfirmed_local.pop_front() else {
450	                break;
451	            };
452	            if ballot != cur_ballot {
453	                // Leadership moved on since this was buffered; the index may
454	                // belong to different writes. Drop tracking -- Local/Remote
455	                // origins simply time out, matching the ballot-mismatch
456	                // handling in `drain_notifiers` for already-assigned entries.
457	                continue;
458	            }
459	            match intent {
460	                TrackIntent::Untracked => {}
461	                TrackIntent::Local(id) => self.record_assignment(id, idx, ballot),
462	                TrackIntent::Remote { id, from } => {
463	                    remote_assigned.entry(from).or_default().push((id, idx));
464	                }
465	            }
466	        }
467	        self.last_seen_accepted_idx = accepted;
468	
469	        for (from, entries) in remote_assigned {
470	            self.enqueue_outgoing(Message::AsyncRuntime(AsyncRuntimeMessage {
471	                from: self.pid,
472	                to: from,
473	                msg: AsyncRuntimeMsg::Assigned {
474	                    ballot: cur_ballot,
475	                    entries,
476	                },
477	            }));
478	        }
479	    }
480	
481	    /// Attempt to dispatch every pending entry that hasn't yet been sent or
482	    /// accepted locally. Called from `Command::AppendNotify` and on each tick,
483	    /// which lets a call issued *before* an election eventually succeed once a
484	    /// leader is known.
485	    fn try_dispatch_undispatched(&mut self) {
486	        let Some((leader, accepted)) = self.op.get_current_leader() else {
487	            return;
488	        };
489	        if leader == self.pid && !accepted {
490	            // We're leader but not yet in Accept phase — leave entries undispatched
491	            // and wait for the next tick.
492	            return;
493	        }
494	        let entries: Vec<(EntryId, T)> = self
495	            .pending
496	            .iter_mut()
497	            .filter_map(|p| p.undispatched.take().map(|entry| (p.id, entry)))
498	            .collect();
499	        if leader == self.pid {
500	            for (id, entry) in entries {
501	                self.accept_as_leader(id, entry, None);
502	            }
503	        } else if !entries.is_empty() {
504	            self.enqueue_outgoing(Message::AsyncRuntime(AsyncRuntimeMessage {
505	                from: self.pid,
506	                to: leader,
507	                msg: AsyncRuntimeMsg::TaggedProposal { entries },
508	            }));
509	        }
510	    }
511	
512	    fn handle_runtime_msg(&mut self, arm: AsyncRuntimeMessage<T>) {
513	        match arm.msg {
514	            AsyncRuntimeMsg::TaggedProposal { entries } => {
515	                let cur = self.op.get_current_leader().map(|(p, _)| p);
516	                if cur == Some(self.pid) {
517	                    // Collect accepted assignments and reply to the origin with a
518	                    // single batched `Assigned`.
519	                    let from = arm.from;
520	                    let assigned: Vec<(EntryId, usize)> = entries
521	                        .into_iter()
522	                        .filter_map(|(id, entry)| self.accept_as_leader(id, entry, Some(from)))
523	                        .collect();
524	                    if !assigned.is_empty() {
525	                        let ballot = self.op.get_promise();
526	                        self.enqueue_outgoing(Message::AsyncRuntime(AsyncRuntimeMessage {
527	                            from: self.pid,
528	                            to: arm.from,
529	                            msg: AsyncRuntimeMsg::Assigned {
530	                                ballot,
531	                                entries: assigned,
532	                            },
533	                        }));
534	                    }
535	                } else if let Some(new_leader) = cur {
536	                    // Leadership drifted since sender chose us. Hop the whole batch
537	                    // forward, preserving the original `from` so the leader replies
538	                    // to the true origin.
539	                    self.enqueue_outgoing(Message::AsyncRuntime(AsyncRuntimeMessage {
540	                        from: arm.from,
541	                        to: new_leader,
542	                        msg: AsyncRuntimeMsg::TaggedProposal { entries },
543	                    }));
544	                }
545	                // Else: no leader; drop. Originators will timeout.
546	            }
547	            AsyncRuntimeMsg::Assigned { ballot, entries } => {
548	                for (id, assigned_idx) in entries {
549	                    self.record_assignment(id, assigned_idx, ballot);
550	                }
551	            }
552	        }
553	    }
554	
555	    /// Given a `(batched_len, accepted_idx)` snapshot taken before some call
556	    /// that may have silently added to the shared batch buffer (a forwarded
557	    /// proposal, an incoming replication batch, a reconfiguration stopsign),
558	    /// pushes a `TrackIntent::Untracked` placeholder in `unconfirmed_local`
559	    /// for each newly-added entry, keeping its FIFO count accurate.
560	    ///
561	    /// Growth is `(accepted_after - accepted_before) + (batched_after -
562	    /// batched_before)`, computed with signed arithmetic and clamped at 0:
563	    /// `accepted_idx` can legitimately *decrease* when a follower's log is
564	    /// truncated by an incoming `AcceptSync` from a new leader, which isn't a
565	    /// case with anything new to track.
566	    fn track_batch_growth(&mut self, batched_before: usize, accepted_before: usize) {
567	        let batched_after = self.op.get_batched_len();
568	        let accepted_after = self.op.get_accepted_idx();
569	        let added = accepted_after as isize - accepted_before as isize + batched_after as isize
570	            - batched_before as isize;
571	        let ballot = self.op.get_promise();
572	        for _ in 0..added.max(0) {
573	            self.unconfirmed_local
574	                .push_back((TrackIntent::Untracked, ballot));
575	        }
576	    }
577	
578	    /// Delivers an incoming `SequencePaxos`/BLE message to the core, tracking
579	    /// any entries it silently adds to the shared batch buffer -- see
580	    /// `track_batch_growth`.
581	    fn handle_incoming_tracked(&mut self, m: Message<T>) {
582	        let batched_before = self.op.get_batched_len();
583	        let accepted_before = self.op.get_accepted_idx();
584	        self.op.handle_incoming(m);
585	        self.track_batch_growth(batched_before, accepted_before);
586	    }
587	
588	    async fn handle_command(&mut self, cmd: Command<T>) {
589	        match cmd {
590	            Command::Append { entry, reply } => {
591	                // Via append_tracked (not self.op.append) so a deferred write
592	                // still gets its unconfirmed_local placeholder, keeping FIFO
593	                // position exact for any append_notify entries batched alongside it.
594	                let res = self
595	                    .append_tracked(TrackIntent::Untracked, entry)
596	                    .map(|_| ());
597	                let _ = reply.send(res);
598	            }
599	            Command::AppendNotify {
600	                entry,
601	                timeout,
602	                reply,
603	            } => {
604	                if self.pending.len() >= self.config.max_pending_appends {
605	                    let _ = reply.send(Err(AppendError::TooManyOutstanding));
606	                    return;
607	                }
608	                let id = EntryId(uuid::Uuid::new_v4());
609	                let timeout = timeout.unwrap_or(self.config.append_notify_timeout);
610	                self.pending.push_back(Pending {
611	                    id,
612	                    undispatched: Some(entry),
613	                    assigned: None,
614	                    deadline: Instant::now() + timeout,
615	                    reply,
616	                });
617	                self.try_dispatch_undispatched();
618	            }
619	            Command::CurrentLeader { reply } => {
620	                let _ = reply.send(self.op.get_current_leader());
621	            }
622	            Command::DecidedIdx { reply } => {
623	                let _ = reply.send(self.op.get_decided_idx());
624	            }
625	            Command::ReadDecidedSuffix { from, reply } => {
626	                let _ = reply.send(self.op.read_decided_suffix(from));
627	            }
628	            Command::SubscribeDecided { from, tx } => {
629	                if self.decided_subscribers.len() >= self.config.max_decided_subscribers {
630	                    // Reject: drop `tx` without storing it, closing the
631	                    // subscriber's channel immediately with no entries delivered.
632	                    return;
633	                }
634	                let mut sub = DecidedSub { next_idx: from, tx };
635	                // Immediate catch-up: push whatever is already decided from `from`.
636	                if Self::push_to_sub(&mut self.op, &mut sub) {
637	                    self.decided_subscribers.push(sub);
638	                }
639	            }
640	            Command::Reconfigure {
641	                new_configuration,
642	                metadata,
643	                reply,
644	            } => {
645	                // Wrapped like handle_incoming_tracked: a stopsign accepted as
646	                // leader is itself an untracked addition to the shared batch buffer.
647	                let batched_before = self.op.get_batched_len();
648	                let accepted_before = self.op.get_accepted_idx();
649	                let res = self.op.reconfigure(new_configuration, metadata);
650	                self.track_batch_growth(batched_before, accepted_before);
651	                let _ = reply.send(res);
652	            }
653	            Command::TryBecomeLeader => {
654	                self.op.try_become_leader();
655	            }
656	            Command::Reconnected { pid } => {
657	                self.op.reconnected(pid);
658	            }
659	        }
660	    }
661	}
662	
663	/// Drives the actor. Runs until all handles are dropped (both `cmd_tx` and
664	/// `incoming_tx` senders closed).
665	pub(crate) async fn run<T, B, R>(mut state: ActorState<T, B>, _rt: PhantomData<fn() -> R>)
666	where
667	    T: ActorEntry,
668	    B: Storage<T> + Send + 'static,
669	    R: AsyncRuntime,
670	{
671	    let mut tick_fut = Box::pin(R::sleep(state.config.tick_period)).fuse();
672	    let mut egress_fut = Box::pin(R::sleep(state.config.egress_period)).fuse();
673	
674	    // async_channel::Receiver is !Unpin; keep it in a Pin<Box<...>> so the Stream
675	    // impl works under select_biased!.
676	    let cmd_rx = std::mem::replace(&mut state.cmd_rx, async_channel::bounded(1).1);
677	    let incoming_rx = std::mem::replace(&mut state.incoming_rx, async_channel::bounded(1).1);
678	    let mut cmd_rx = Box::pin(cmd_rx);
679	    let mut incoming_rx = Box::pin(incoming_rx);
680	
681	    loop {
682	        select_biased! {
683	            _ = tick_fut => {
684	                state.op.tick();
685	                state.detect_and_emit_events().await;
686	                state.try_dispatch_undispatched();
687	                state.reconcile_unconfirmed();
688	                state.drain_notifiers();
689	                state.push_to_all_subs();
690	                tick_fut = Box::pin(R::sleep(state.config.tick_period)).fuse();
691	            }
692	            _ = egress_fut => {
693	                state.flush_outgoing();
694	                egress_fut = Box::pin(R::sleep(state.config.egress_period)).fuse();
695	            }
696	            in_msg = incoming_rx.next() => {
697	                match in_msg {
698	                    Some(Message::AsyncRuntime(arm)) => state.handle_runtime_msg(arm),
699	                    Some(m) => state.handle_incoming_tracked(m),
700	                    None => break,
701	                }
702	            }
703	            cmd = cmd_rx.next() => {
704	                match cmd {
705	                    Some(c) => state.handle_command(c).await,
706	                    None => break,
707	                }
708	            }
709	        }
710	    }
711	}
