713	/// Drops the oldest elements of `buf` until its length is at most `cap`, preserving
714	/// the relative order of what remains. A no-op if `buf` is already within `cap`.
715	fn trim_oldest<M>(buf: &mut Vec<M>, cap: usize) {
716	    if buf.len() > cap {
717	        let excess = buf.len() - cap;
718	        buf.drain(..excess);
719	    }
720	}
721	
