723	mod tests {
724	    use super::trim_oldest;
725	
726	    #[test]
727	    fn trim_oldest_drops_front_keeps_cap_most_recent() {
728	        let mut buf = vec![1, 2, 3, 4, 5];
729	        trim_oldest(&mut buf, 3);
730	        assert_eq!(buf, vec![3, 4, 5]);
731	    }
732	
733	    #[test]
734	    fn trim_oldest_is_noop_when_within_cap() {
735	        let mut buf = vec![1, 2, 3];
736	        trim_oldest(&mut buf, 5);
737	        assert_eq!(buf, vec![1, 2, 3]);
738	    }
739	
740	    #[test]
741	    fn trim_oldest_is_noop_when_exactly_at_cap() {
742	        let mut buf = vec![1, 2, 3];
743	        trim_oldest(&mut buf, 3);
744	        assert_eq!(buf, vec![1, 2, 3]);
745	    }
746	
747	    #[test]
748	    fn trim_oldest_can_drop_everything() {
749	        let mut buf = vec![1, 2, 3];
750	        trim_oldest(&mut buf, 0);
751	        assert!(buf.is_empty());
752	    }
